export const regionScenes6: Record<string, SceneModule> = bindContentSource("data:src/lib/scenes/regions6.ts#regionScenes6", {
  "dam-roi-canh-tay": {
    slug: "dam-roi-canh-tay",
    title: { vi: "Đám rối thần kinh cánh tay", en: "The Brachial Plexus", zh: "臂丛" },
    description: {
      vi: "Toàn bộ đường đi của thần kinh chi trên, từ rễ C5–T1 chui ra khe cơ bậc thang, hợp thành ba thân ở nền cổ, chia sáu ngành trước – sau sau xương đòn, gộp thành ba bó quanh động mạch nách rồi tách ra năm dây tận. Đám rối là chỗ mà giải phẫu quyết định trực tiếp triệu chứng: tổn thương ở tầng nào cho liệt đúng nhóm cơ của tầng ấy, nên chỉ cần khám vận động – cảm giác là định khu được vị trí đứt. Rễ trên (C5–C6) bị kéo giãn cho tư thế “bồi bàn xin tiền” của liệt Erb; rễ dưới (C8–T1) bị kéo cho bàn tay vuốt trụ của liệt Klumpke. Mô hình dựng ba thân, sáu ngành, bó sau và các dây tận cùng với xương đòn, xương sườn I và ba cơ bậc thang — đúng những mốc dùng để gây tê đám rối.",
      en: "The whole nerve supply of the upper limb: roots C5–T1 emerging between the scalenes, three trunks at the root of the neck, six anterior and posterior divisions behind the clavicle, three cords around the axillary artery, and five terminal nerves. This is anatomy that dictates symptoms directly — the level of the lesion selects the paralysed muscle groups, so a motor and sensory examination localises the break. Upper-root traction gives the waiter's-tip posture of Erb palsy; lower-root traction gives the claw hand of Klumpke palsy. The model carries the trunks, divisions, posterior cord and terminal nerves together with the clavicle, first rib and the three scalene muscles — the very landmarks used for plexus blocks.",
      zh: "上肢神经供应的全程：C5–T1神经根自斜角肌间隙穿出，于颈根部合成三干，锁骨后分为前后六股，绕腋动脉合成三束，终成五条终末神经。此处解剖直接决定症状——损伤平面决定瘫痪肌群，故运动与感觉检查即可定位。上干牵拉致Erb麻痹的“侍者手”姿势；下干牵拉致Klumpke麻痹的爪形手。模型含各干、股、后束与终末神经，以及锁骨、第一肋和三块斜角肌——正是臂丛阻滞所用的标志。",
    },
    visibleSystems: ["nervous", "cardiovascular", "muscular", "skeletal"],
    modelFile: "/models/brachial_plexus.glb",
    hotspots: [
      { key: "roots", meshName: "Roots of brachial plexus.r.001", offset: [0, 0], label: { vi: "Rễ đám rối (C5–T1)", en: "Roots of the brachial plexus (C5–T1)", zh: "臂丛神经根（C5–T1）" }, latinName: "Radices plexus brachialis",
        note: { vi: "Năm ngành trước của thần kinh sống C5, C6, C7, C8 và T1 chui ra ở KHE CƠ BẬC THANG, giữa cơ bậc thang trước và cơ bậc thang giữa, cùng đường với động mạch dưới đòn. Khe này chính là chỗ hẹp gây hội chứng lối thoát ngực: xương sườn cổ bẩm sinh hoặc cơ bậc thang phì đại chèn vào rễ dưới, gây tê bờ trụ cẳng tay và teo cơ ô mô cái.", en: "The anterior rami of C5–T1 emerge in the INTERSCALENE GROOVE between scalenus anterior and medius, alongside the subclavian artery. That groove is the narrow point of thoracic outlet syndrome: a cervical rib or hypertrophied scalene compresses the lower roots, causing ulnar-border numbness and thenar wasting.", zh: "C5–T1的前支于前、中斜角肌之间的斜角肌间隙穿出，与锁骨下动脉同行。该间隙即胸廓出口综合征的狭窄处：颈肋或斜角肌肥厚压迫下位神经根，引起前臂尺侧麻木与鱼际肌萎缩。" } },
      { key: "superior-trunk", meshName: "Superior trunk of brachial plexus.r.001", offset: [0, 0], label: { vi: "Thân trên (C5–C6)", en: "Superior trunk (C5–C6)", zh: "上干（C5–C6）" }, latinName: "Truncus superior",
        note: { vi: "C5 và C6 hợp lại thành thân trên ở bờ ngoài cơ bậc thang trước — điểm ERB, nơi nằm nông nhất của cả đám rối và cũng là mốc gây tê đám rối đường liên cơ bậc thang. Kéo giãn mạnh vai xuống và đầu sang bên (đẻ khó kẹt vai, ngã xe máy) làm đứt đúng chỗ này: mất dạng vai, mất gấp khuỷu, mất xoay ngoài — tay xoay sấp ép sát thân.", en: "C5 and C6 unite at the lateral border of scalenus anterior — ERB's point, the most superficial part of the plexus and the target of the interscalene block. Violent depression of the shoulder with lateral flexion of the head (shoulder dystocia, motorcycle falls) ruptures exactly here: loss of abduction, elbow flexion and external rotation, leaving the arm adducted and pronated.", zh: "C5与C6于前斜角肌外缘合成上干——即Erb点，臂丛最浅处，也是肌间沟阻滞的靶点。肩部被强力下压伴头侧屈（肩难产、摩托车摔伤）恰在此处断裂：肩外展、屈肘与外旋丧失，上肢内收旋前。" } },
      { key: "middle-trunk", meshName: "Middle trunk of brachial plexus.r.001", offset: [0, 0], label: { vi: "Thân giữa (C7)", en: "Middle trunk (C7)", zh: "中干（C7）" }, latinName: "Truncus medius",
        note: { vi: "Do một mình ngành trước C7 kéo dài thành, không hợp với rễ nào. Phần lớn sợi của nó đi vào NGÀNH SAU rồi vào bó sau và thần kinh quay, nên tổn thương riêng C7 biểu hiện chủ yếu ở yếu duỗi khuỷu, duỗi cổ tay và duỗi ngón — kèm mất phản xạ gân cơ tam đầu.", en: "The anterior ramus of C7 alone continues as the middle trunk. Most of its fibres pass into the POSTERIOR division, the posterior cord and the radial nerve, so an isolated C7 lesion mainly weakens elbow, wrist and finger extension, with a lost triceps reflex.", zh: "由C7前支单独延续而成。其纤维大多进入后股、后束与桡神经，故孤立性C7损伤主要表现为伸肘、伸腕与伸指无力，肱三头肌反射消失。" } },
      { key: "inferior-trunk", meshName: "Inferior trunk of brachial plexus.r.001", offset: [0, 0], label: { vi: "Thân dưới (C8–T1)", en: "Inferior trunk (C8–T1)", zh: "下干（C8–T1）" }, latinName: "Truncus inferior",
        note: { vi: "Nằm THẤP NHẤT, vắt ngay trên xương sườn I ở phía sau động mạch dưới đòn. Vị trí đó khiến nó chịu ba tai hoạ đặc trưng: kéo giãn khi cánh tay bị giật lên quá đầu (liệt Klumpke, bàn tay vuốt trụ vì mất cơ nội tại), chèn ép bởi xương sườn cổ, và bị u đỉnh phổi Pancoast ăn lan gây đau vai lan xuống bờ trụ kèm hội chứng Horner do tổn thương sợi giao cảm T1.", en: "The LOWEST element, arching directly over the first rib behind the subclavian artery. That position gives it three characteristic disasters: traction when the arm is wrenched overhead (Klumpke palsy with a claw hand from intrinsic loss), compression by a cervical rib, and invasion by a Pancoast tumour causing shoulder pain radiating to the ulnar border with a Horner syndrome from the T1 sympathetic fibres.", zh: "位置最低，紧贴第一肋并位于锁骨下动脉后方。此位置带来三种典型灾难：上肢被强力上举牵拉（Klumpke麻痹，因内在肌丧失呈爪形手）、颈肋压迫，以及Pancoast肺尖肿瘤侵犯，引起肩痛向尺侧放射并因T1交感纤维受损而出现Horner综合征。" } },
      { key: "posterior-cord", meshName: "Posterior cord of brachial plexus.r.001", offset: [0, 0], label: { vi: "Bó sau", en: "Posterior cord", zh: "后束" }, latinName: "Fasciculus posterior",
        note: { vi: "Do BA NGÀNH SAU của cả ba thân gộp lại, nằm sau động mạch nách. Vì gom sợi của cả C5 tới T1, bó sau là nguồn của mọi cơ DUỖI ở chi trên: nó cho thần kinh nách, thần kinh quay, hai thần kinh dưới vai và thần kinh ngực lưng. Tổn thương bó sau vì thế cho một bức tranh rất dễ nhận: mất dạng vai cộng bàn tay rủ.", en: "Formed by the THREE POSTERIOR divisions of all trunks, lying behind the axillary artery. Because it gathers fibres from C5 to T1, it supplies every EXTENSOR of the upper limb: the axillary and radial nerves, both subscapular nerves and the thoracodorsal nerve. A posterior-cord lesion is therefore easy to read — loss of shoulder abduction plus wrist drop.", zh: "由三干的后股合成，位于腋动脉后方。因汇集C5至T1的纤维，后束供应上肢全部伸肌：发出腋神经、桡神经、肩胛下神经与胸背神经。故后束损伤表现鲜明：肩外展丧失合并垂腕。" } },
      { key: "median-nerve", meshName: "Median nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh giữa", en: "Median nerve", zh: "正中神经" }, latinName: "Nervus medianus",
        note: { vi: "Hình thành từ HAI RỄ — rễ ngoài của bó ngoài và rễ trong của bó trong — ôm lấy động mạch nách thành chữ M đặc trưng, mốc nhận dạng chắc chắn nhất khi phẫu tích hố nách. Nó chi phối gần hết cơ gấp cẳng tay và cơ ô mô cái, nên là “thần kinh của động tác cầm nắm”; chỗ hẹp cuối đường của nó là ống cổ tay.", en: "Formed by TWO ROOTS — lateral from the lateral cord, medial from the medial cord — embracing the axillary artery in the characteristic M shape, the surest landmark when dissecting the axilla. It supplies almost all forearm flexors and the thenar muscles, making it the nerve of grip; its final narrow passage is the carpal tunnel.", zh: "由外侧束的外侧根与内侧束的内侧根合成，夹持腋动脉呈特征性“M”形，是腋窝解剖最可靠的标志。其支配几乎全部前臂屈肌与鱼际肌，为“抓握之神经”；其行程末端的狭窄处即腕管。" } },
      { key: "ulnar-nerve", meshName: "Ulnar nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh trụ", en: "Ulnar nerve", zh: "尺神经" }, latinName: "Nervus ulnaris",
        note: { vi: "Dây tận của bó trong, mang chủ yếu sợi C8–T1. Nó chi phối gần như toàn bộ CƠ NỘI TẠI của bàn tay, nên mất nó là mất động tác tinh vi: các ngón không khép được, dấu Froment dương tính, bàn tay dần thành hình vuốt. Đường đi nông ở rãnh sau mỏm trên lồi cầu trong là lý do vì sao chạm khuỷu vào cạnh bàn lại tê buốt cả hai ngón út.", en: "The terminal branch of the medial cord, carrying mostly C8–T1 fibres. It supplies nearly all the INTRINSIC muscles of the hand, so losing it costs fine movement: the fingers cannot adduct, Froment's sign is positive, and the hand slowly claws. Its superficial course in the groove behind the medial epicondyle explains the electric tingling into the little finger when the elbow is knocked.", zh: "内侧束的终支，主要含C8–T1纤维。支配手内在肌的绝大部分，故其损伤丧失精细动作：手指不能内收，Froment征阳性，手渐成爪形。其在肱骨内上髁后沟的浅表走行，解释了肘部撞击时小指的触电样麻感。" } },
      { key: "radial-nerve", meshName: "Radial nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh quay", en: "Radial nerve", zh: "桡神经" }, latinName: "Nervus radialis",
        note: { vi: "Dây TẬN LỚN NHẤT của đám rối, nối dài bó sau. Nó vòng quanh mặt sau xương cánh tay trong rãnh thần kinh quay — áp sát xương ở đúng đoạn hay gãy thân xương cánh tay, và cũng là chỗ bị ép khi ngủ gục tay lên thành ghế (“liệt đêm thứ bảy”). Hậu quả kinh điển là bàn tay rủ vì mất mọi cơ duỗi cổ tay và duỗi ngón.", en: "The LARGEST terminal branch, continuing the posterior cord. It spirals around the back of the humerus in the radial groove — pressed against bone exactly where the shaft fractures, and compressed by sleeping with the arm over a chair back (Saturday-night palsy). The classic result is wrist drop from loss of all wrist and finger extensors.", zh: "臂丛最粗的终支，为后束的延续。其绕肱骨后方的桡神经沟走行——紧贴骨面，恰位于肱骨干骨折好发段，也是手臂搭椅背入睡时的受压处（周六夜麻痹）。典型后果为垂腕，因全部伸腕伸指肌丧失。" } },
      { key: "musculocutaneous", meshName: "Musculocutaneous nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh cơ bì", en: "Musculocutaneous nerve", zh: "肌皮神经" }, latinName: "Nervus musculocutaneus",
        note: { vi: "Rời bó ngoài rồi XUYÊN QUA cơ quạ cánh tay — đặc điểm nhận dạng duy nhất trong hố nách. Nó chi phối ba cơ khoang trước cánh tay (quạ cánh tay, nhị đầu, cánh tay) rồi tiếp tục làm thần kinh bì cẳng tay ngoài, nên mất nó là mất gấp khuỷu chủ động cùng mảng tê ở mặt ngoài cẳng tay.", en: "It leaves the lateral cord and PIERCES coracobrachialis — its unique identifying feature in the axilla. It supplies the three anterior compartment muscles of the arm (coracobrachialis, biceps, brachialis) and continues as the lateral cutaneous nerve of the forearm, so its loss costs active elbow flexion plus numbness over the lateral forearm.", zh: "自外侧束发出后穿过喙肱肌——腋窝内独特的识别特征。支配臂前群三肌（喙肱肌、肱二头肌、肱肌），继而延续为前臂外侧皮神经，故其损伤致主动屈肘丧失并前臂外侧麻木。" } },
      { key: "long-thoracic", meshName: "Long thoracic nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh ngực dài", en: "Long thoracic nerve", zh: "胸长神经" }, latinName: "Nervus thoracicus longus",
        note: { vi: "Tách thẳng từ RỄ C5–C7 rồi chạy dọc mặt ngoài thành ngực để chi phối riêng cơ răng trước. Vì nằm nông trên mặt cơ, nó hay bị cắt trong phẫu thuật nạo hạch nách; hậu quả là XƯƠNG BẢ VAI CÁNH — bờ trong bả vai bật khỏi lồng ngực khi bệnh nhân đẩy tay vào tường.", en: "Arises directly from ROOTS C5–C7 and runs on the outer chest wall to supply serratus anterior alone. Lying superficially on the muscle, it is easily divided during axillary node clearance; the result is a WINGED SCAPULA — the medial border lifting off the chest when the patient pushes against a wall.", zh: "直接发自C5–C7神经根，沿胸壁外侧下行，仅支配前锯肌。因浅置于肌面，腋窝淋巴结清扫时易被切断；结果为翼状肩胛——患者推墙时肩胛骨内侧缘翘离胸壁。" } },
      { key: "axillary-artery", meshName: "Axillary artery.r.001", offset: [0, 0], label: { vi: "Động mạch nách", en: "Axillary artery", zh: "腋动脉" }, latinName: "Arteria axillaris",
        note: { vi: "Nối tiếp động mạch dưới đòn từ bờ ngoài xương sườn I, được cơ ngực bé bắc ngang chia thành BA ĐOẠN — cách chia này không phải hình thức: mỗi đoạn cho đúng một, hai rồi ba nhánh, và ba bó thần kinh được đặt tên (ngoài, trong, sau) chính theo vị trí của chúng quanh đoạn hai.", en: "The continuation of the subclavian artery from the outer border of the first rib, crossed by pectoralis minor which divides it into THREE PARTS — not a formality: the parts give one, two and three branches respectively, and the three cords are named (lateral, medial, posterior) by their position around the second part.", zh: "自第一肋外缘续锁骨下动脉，胸小肌横跨其上将其分为三段——此划分并非形式：三段分别发出一、二、三条分支，而三束（外侧、内侧、后束）正是依其在第二段周围的位置命名。" } },
      { key: "scalenus-anterior", meshName: "Scalenus anterior muscle.r", offset: [0, 0], label: { vi: "Cơ bậc thang trước", en: "Scalenus anterior", zh: "前斜角肌" }, latinName: "Musculus scalenus anterior",
        note: { vi: "Bám từ mỏm ngang các đốt sống cổ xuống củ cơ bậc thang của xương sườn I, là mốc CHÌA KHOÁ của nền cổ: tĩnh mạch dưới đòn đi TRƯỚC cơ, còn động mạch dưới đòn và đám rối đi SAU cơ. Nhớ đúng một câu đó là định vị được mọi cấu trúc trong tam giác này, kể cả khi giải phẫu mờ vì máu tụ.", en: "Running from the cervical transverse processes to the scalene tubercle of the first rib, it is the KEY landmark of the root of the neck: the subclavian vein passes IN FRONT of it, the subclavian artery and the plexus BEHIND it. That single rule locates everything in the triangle, even when a haematoma blurs the field.", zh: "起自颈椎横突，止于第一肋斜角肌结节，是颈根部的关键标志：锁骨下静脉经其前方，锁骨下动脉与臂丛经其后方。仅此一条即可定位该三角内的全部结构，即使血肿使术野模糊。" } },
      { key: "clavicle", meshName: "Clavicle.r", offset: [0, 0], label: { vi: "Xương đòn", en: "Clavicle", zh: "锁骨" }, latinName: "Clavicula",
        note: { vi: "Nằm vắt ngang trên đám rối và chia đám rối thành phần TRÊN đòn (rễ, thân) và phần DƯỚI đòn (bó, dây tận) — cách chia dùng hằng ngày trong gây tê vùng. Gãy xương đòn ở một phần ba giữa vì thế có thể kèm tổn thương đám rối hoặc mạch dưới đòn, luôn phải khám mạch và thần kinh chi trên trước khi bó bột.", en: "It crosses over the plexus and splits it into a SUPRAclavicular part (roots, trunks) and an INFRAclavicular part (cords, terminal nerves) — the division used daily in regional anaesthesia. A middle-third clavicular fracture may therefore injure the plexus or the subclavian vessels, so limb pulses and nerves must be checked before immobilisation.", zh: "横跨臂丛上方，将其分为锁骨上部（根、干）与锁骨下部（束、终末神经）——此划分为区域麻醉日常所用。故锁骨中1/3骨折可合并臂丛或锁骨下血管损伤，固定前必须检查上肢脉搏与神经。" } },
    ],
  },

  "than-kinh-tu-chu": {
    slug: "than-kinh-tu-chu",
    title: { vi: "Thần kinh tự chủ: chuỗi hạch giao cảm và dây X", en: "Autonomic Nerves: Sympathetic Trunk and Vagus", zh: "自主神经：交感干与迷走神经" },
    description: {
      vi: "Hai hệ điều hoà nội tạng đặt cạnh nhau để thấy rõ sự đối lập về hình thái. Chuỗi hạch GIAO CẢM là hai dây hạt cườm chạy dọc hai bên cột sống từ nền sọ tới xương cụt, hạch nằm SÁT tủy nên sợi trước hạch ngắn và sợi sau hạch dài — một sợi trước hạch toả tới hàng chục hạch, nhờ vậy phản ứng giao cảm lan rộng toàn thân. Dây X PHÓ GIAO CẢM thì ngược lại: đi thẳng một mạch từ hành não xuống tận góc lách, hạch nằm ngay trong thành tạng nên sợi trước hạch rất dài và sợi sau hạch cực ngắn, cho tác dụng khu trú từng tạng. Mô hình giữ lại cột sống và lồng ngực làm mốc để thấy đúng vị trí cạnh sống của chuỗi hạch và đường đi cạnh thực quản của dây X.",
      en: "The two visceral control systems side by side, so that their opposite architecture shows. The SYMPATHETIC trunk is a beaded chain running beside the vertebral column from skull base to coccyx; its ganglia sit CLOSE to the cord, so preganglionic fibres are short and postganglionic ones long — one preganglionic fibre reaches dozens of ganglia, which is why sympathetic responses are body-wide. The PARASYMPATHETIC vagus is the opposite: a single long run from the medulla to the splenic flexure, with ganglia inside the organ walls, so preganglionic fibres are very long and postganglionic ones minimal, giving organ-by-organ control. The spine and rib cage are kept as landmarks for the paravertebral chain and the para-oesophageal course of the vagus.",
      zh: "两大内脏调控系统并置，凸显其相反的构筑。交感干为脊柱两侧自颅底至尾骨的串珠状链，神经节靠近脊髓，故节前纤维短而节后纤维长——一条节前纤维可达数十个节，交感反应因而遍及全身。副交感的迷走神经则相反：自延髓一路下行至脾曲，神经节位于器官壁内，节前纤维极长而节后纤维极短，实现逐器官的局部调控。保留脊柱与胸廓作为标志，以显示椎旁链的位置与迷走神经沿食管的走行。",
    },
    visibleSystems: ["nervous", "skeletal", "cardiovascular", "visceral"],
    modelFile: "/models/autonomic_nerves.glb",
    hotspots: [
      { key: "sympathetic-trunk-r", meshName: "Sympathetic trunk.r.001", offset: [0, 0], label: { vi: "Chuỗi hạch giao cảm (phải)", en: "Sympathetic trunk (right)", zh: "交感干（右）" }, latinName: "Truncus sympathicus",
        note: { vi: "Dây thần kinh chạy dọc CẠNH SỐNG, ngay trước đầu các xương sườn ở đoạn ngực. Vị trí ấy giải thích vì sao phẫu thuật cắt hạch giao cảm ngực chữa ra mồ hôi tay lại làm qua nội soi lồng ngực: chỉ cần vén màng phổi thành là thấy chuỗi hạch nằm sẵn trên cổ sườn.", en: "A nerve running PARAVERTEBRALLY, just in front of the rib heads in the thoracic region. That position explains why thoracoscopic sympathectomy for palmar hyperhidrosis works: peeling back the parietal pleura exposes the chain lying on the rib necks.", zh: "沿椎旁走行，胸段恰位于肋骨头前方。此位置解释了胸腔镜交感神经切断术治疗手汗症的可行性：掀开壁胸膜即见交感链位于肋颈之上。" } },
      { key: "sympathetic-ganglia-r", meshName: "Ganglia of sympathetic trunk.r", offset: [0, 0], label: { vi: "Các hạch giao cảm cạnh sống", en: "Paravertebral sympathetic ganglia", zh: "椎旁交感神经节" }, latinName: "Ganglia trunci sympathici",
        note: { vi: "Mỗi đốt một hạch, hình hạt cườm nối nhau bằng đoạn dây liên hạch. Sợi trước hạch từ sừng bên tuỷ T1–L2 vào hạch rồi có ba lựa chọn: dừng lại tại hạch cùng tầng, đi lên hay xuống vài tầng, hoặc XUYÊN QUA hạch mà không dừng để đi tới hạch trước tạng. Chính lựa chọn thứ ba tạo ra các dây tạng lớn – bé nuôi đám rối tạng ở bụng.", en: "One ganglion per segment, beads linked by interganglionic cords. Preganglionic fibres from the lateral horn of T1–L2 enter and have three options: synapse at the same level, run up or down a few levels, or PASS THROUGH without synapsing to reach a prevertebral ganglion. That third option creates the greater and lesser splanchnic nerves supplying the abdominal coeliac plexus.", zh: "每节一个神经节，串珠状由节间支相连。来自T1–L2侧角的节前纤维进入后有三种去向：同节换元、上下行数节换元，或穿过而不换元直达椎前神经节。第三种去向形成内脏大、小神经，供应腹部腹腔丛。" } },
      { key: "sympathetic-nerves-r", meshName: "Sympathetic nerves.r.001", offset: [0, 0], label: { vi: "Nhánh giao cảm tới tạng", en: "Sympathetic branches to viscera", zh: "至内脏的交感支" }, latinName: "Nervi splanchnici",
        note: { vi: "Các nhánh rời chuỗi hạch đi vào ngực và bụng. Đây là đường dẫn ĐAU TẠNG: cảm giác đau từ tim, dạ dày hay ruột đi ngược theo sợi giao cảm về tuỷ ở đúng tầng mà một vùng da cũng đổ về — nên nhồi máu cơ tim đau lan tay trái, sỏi mật đau lan bả vai phải. Đau quy chiếu không phải hiện tượng kỳ lạ mà là hệ quả trực tiếp của cách đi dây này.", en: "Branches leaving the chain for the thorax and abdomen. This is the pathway of VISCERAL PAIN: nociception from heart, stomach or gut travels back along sympathetic fibres to the same cord segments that receive a skin area — hence myocardial pain in the left arm and gallbladder pain at the right scapula. Referred pain is a direct consequence of this wiring.", zh: "离开交感链进入胸腹的分支。此为内脏痛通路：心、胃或肠的伤害性感觉沿交感纤维返回与某皮区相同的脊髓节段——故心肌梗死牵涉左臂、胆囊病变牵涉右肩胛。牵涉痛正是此种布线的直接结果。" } },
      { key: "vagus-r", meshName: "Vagus nerve (X).r.001", offset: [0, 0], label: { vi: "Thần kinh lang thang phải (X)", en: "Right vagus nerve (X)", zh: "右迷走神经（X）" }, latinName: "Nervus vagus dexter",
        note: { vi: "Đi xuống trước động mạch dưới đòn phải, cho thần kinh thanh quản quặt ngược VÒNG DƯỚI mạch này, rồi bám mặt SAU thực quản. Vì hai dây X xoắn quanh thực quản khi ống tiêu hoá quay trong phôi, dây phải kết thúc ở mặt sau còn dây trái ra mặt trước — đúng thứ tự phải nhớ khi cắt dây X điều trị loét dạ dày.", en: "It descends in front of the right subclavian artery, gives a recurrent laryngeal nerve that HOOKS UNDER that vessel, then lies on the POSTERIOR surface of the oesophagus. Because the two vagi rotate with the embryonic gut, the right ends up behind and the left in front — the order to remember when dividing the vagus for peptic ulcer.", zh: "于右锁骨下动脉前方下行，发出喉返神经勾绕该动脉下方，继而贴附食管后面。因胚胎期肠管旋转使两迷走神经缠绕食管，右侧转至后方、左侧至前方——此顺序为溃疡病迷走神经切断术所必记。" } },
      { key: "vagus-l", meshName: "Vagus nerve (X).l.001", offset: [0, 0], label: { vi: "Thần kinh lang thang trái (X)", en: "Left vagus nerve (X)", zh: "左迷走神经（X）" }, latinName: "Nervus vagus sinister",
        note: { vi: "Đi vào ngực giữa động mạch cảnh chung trái và động mạch dưới đòn trái, cho thần kinh thanh quản quặt ngược trái vòng dưới QUAI ĐỘNG MẠCH CHỦ. Đường vòng dài ấy khiến khàn tiếng trở thành dấu hiệu của bệnh trong lồng ngực: phình quai chủ, hạch trung thất hay ung thư phổi trái đều có thể ép dây này.", en: "It enters the thorax between the left common carotid and left subclavian arteries and gives a left recurrent laryngeal nerve hooking under the AORTIC ARCH. That long detour makes hoarseness a sign of intrathoracic disease: aortic arch aneurysm, mediastinal nodes or a left lung cancer can all compress it.", zh: "于左颈总动脉与左锁骨下动脉之间入胸，发出左喉返神经勾绕主动脉弓。此长途迂回使声嘶成为胸内疾病的体征：主动脉弓瘤、纵隔淋巴结或左肺癌均可压迫之。" } },
      { key: "intercostal-nerves", meshName: "Intercostal nerves.r.001", offset: [0, 0], label: { vi: "Thần kinh gian sườn", en: "Intercostal nerves", zh: "肋间神经" }, latinName: "Nervi intercostales",
        note: { vi: "Ngành trước của thần kinh sống ngực, đi trong rãnh bờ dưới xương sườn cùng động và tĩnh mạch theo thứ tự TĨNH – ĐỘNG – THẦN từ trên xuống. Chọc dò màng phổi phải đi sát bờ TRÊN xương sườn dưới chính vì bó mạch – thần kinh nằm nép bờ dưới xương sườn trên. Mỗi hạch giao cảm nối với dây này bằng nhánh thông trắng và xám.", en: "The anterior rami of the thoracic spinal nerves, running in the subcostal groove with the vessels in the order VEIN – ARTERY – NERVE from above down. Pleural puncture must hug the UPPER border of the lower rib precisely because the neurovascular bundle tucks under the rib above. Each sympathetic ganglion connects to these nerves by white and grey rami communicantes.", zh: "胸神经前支，行于肋下沟内，自上而下依次为静脉、动脉、神经。胸膜穿刺必须紧贴下位肋骨上缘，正因血管神经束藏于上位肋骨下缘。各交感神经节经白交通支与灰交通支与之相连。" } },
      { key: "oesophagus", meshName: "Oesophagus.001", offset: [0, 0], label: { vi: "Thực quản", en: "Oesophagus", zh: "食管" }, latinName: "Oesophagus",
        note: { vi: "Được cả hai dây X bám theo tạo thành ĐÁM RỐI THỰC QUẢN trên bề mặt, rồi tụ lại thành thân lang thang trước và sau trước khi chui qua cơ hoành. Đám rối này chi phối nhu động thực quản; mất tế bào hạch trong thành gây co thắt tâm vị, bệnh nuốt nghẹn điển hình mà phim chụp cho hình “mỏ chim”.", en: "Both vagi cling to it as a surface OESOPHAGEAL PLEXUS, regathering into anterior and posterior vagal trunks before piercing the diaphragm. This plexus drives oesophageal peristalsis; loss of the intramural ganglion cells causes achalasia, the classic dysphagia with a bird-beak barium swallow.", zh: "两条迷走神经贴附其上形成食管丛，再汇成迷走前干与后干穿膈。此丛驱动食管蠕动；壁内节细胞丧失致贲门失弛缓症，即钡餐呈“鸟嘴征”的典型吞咽困难。" } },
      { key: "thoracic-aorta", meshName: "Thoracic aorta.001", offset: [0, 0], label: { vi: "Động mạch chủ ngực", en: "Thoracic aorta", zh: "胸主动脉" }, latinName: "Aorta thoracica",
        note: { vi: "Nằm cạnh sống bên trái, ngay TRƯỚC chuỗi hạch giao cảm trái và cạnh thực quản — ba cấu trúc chen nhau trong một khoảng hẹp là lý do phình động mạch chủ ngực có thể vừa gây nuốt nghẹn vừa gây khàn tiếng mà chưa hề vỡ.", en: "Lying paravertebrally on the left, just IN FRONT of the left sympathetic chain and beside the oesophagus — three structures crowded into a narrow space, which is why a thoracic aortic aneurysm can cause dysphagia and hoarseness long before it ruptures.", zh: "位于左侧椎旁，恰在左交感链前方并紧邻食管——三者挤于狭窄空间，故胸主动脉瘤远在破裂之前即可引起吞咽困难与声嘶。" } },
      { key: "trachea", meshName: "Trachea", offset: [0, 0], label: { vi: "Khí quản", en: "Trachea", zh: "气管" }, latinName: "Trachea",
        note: { vi: "Nhận sợi phó giao cảm từ dây X (co cơ trơn phế quản, tăng tiết) và sợi giao cảm từ chuỗi hạch (giãn phế quản). Chính sự đối lập ấy là nền của điều trị hen: thuốc cường beta-2 bắt chước giao cảm để giãn phế quản, thuốc kháng cholinergic chặn dây X để cắt co thắt.", en: "It receives parasympathetic fibres from the vagus (bronchoconstriction, secretion) and sympathetic fibres from the chain (bronchodilation). That opposition underlies asthma treatment: beta-2 agonists mimic the sympathetic side to dilate, anticholinergics block the vagal side to relieve spasm.", zh: "接受迷走神经的副交感纤维（支气管收缩、分泌增加）与交感链的交感纤维（支气管舒张）。此对抗即哮喘治疗的基础：β2受体激动剂模拟交感以舒张，抗胆碱药阻断迷走以解痉。" } },
      { key: "vertebra-t6", meshName: "Vertebra T6", offset: [0, 0], label: { vi: "Đốt sống ngực T6", en: "Thoracic vertebra T6", zh: "第6胸椎" }, latinName: "Vertebra thoracica VI",
        note: { vi: "Mốc để định tầng cho chuỗi hạch: hạch giao cảm ngực nằm ngay trước CỔ XƯƠNG SƯỜN cùng tên. Trong cắt hạch giao cảm, đếm xương sườn từ trên xuống là cách duy nhất xác định đúng tầng, vì các hạch trông giống hệt nhau.", en: "The level marker for the chain: each thoracic ganglion lies just in front of the RIB NECK of the same number. In sympathectomy, counting ribs from above is the only way to identify the correct level, since the ganglia look identical.", zh: "交感链的定位标志：各胸神经节恰位于同序数肋骨颈前方。交感神经切断术中，自上而下数肋骨是确认节段的唯一方法，因各神经节外观相同。" } },
    ],
  },

  "duong-thi-giac": {
    slug: "duong-thi-giac",
    title: { vi: "Đường dẫn truyền thị giác", en: "The Visual Pathway", zh: "视觉传导通路" },
    description: {
      vi: "Từ võng mạc tới vỏ não thị giác, đi qua đúng năm chặng: võng mạc → thần kinh thị → giao thoa thị giác → dải thị → thể gối ngoài → tia thị → vỏ quanh rãnh cựa. Đây là đường dẫn truyền mà mỗi chặng cắt ngang cho MỘT kiểu khuyết thị trường riêng biệt, nên hỏi bệnh nhân mất nửa thị trường nào là biết ngay tổn thương ở đâu — không cần chụp chiếu. Chìa khoá nằm ở giao thoa: sợi từ nửa võng mạc MŨI của mỗi mắt bắt chéo sang bên đối diện, sợi nửa thái dương đi thẳng, nên từ sau giao thoa mọi thứ đều được xếp theo NỬA THỊ TRƯỜNG chứ không theo mắt nữa. Mô hình dựng cả hai nhãn cầu, giao thoa, dải thị, thể gối ngoài và vỏ chẩm quanh rãnh cựa.",
      en: "From retina to visual cortex in exactly five relays: retina → optic nerve → optic chiasm → optic tract → lateral geniculate body → optic radiation → cortex around the calcarine sulcus. Each level, when cut, produces ONE characteristic field defect, so asking which half-field is lost localises the lesion without imaging. The key is the chiasm: fibres from the NASAL half of each retina cross, temporal fibres stay ipsilateral, so beyond the chiasm everything is organised by HALF-FIELD rather than by eye. The model carries both globes, the chiasm, optic tracts, lateral geniculate bodies and the occipital cortex around the calcarine sulcus.",
      zh: "自视网膜至视皮质，恰经五级中继：视网膜→视神经→视交叉→视束→外侧膝状体→视辐射→距状沟周围皮质。各级损伤各产生一种特征性视野缺损，故询问缺失的半视野即可定位，无需影像。关键在视交叉：各眼视网膜鼻侧半的纤维交叉，颞侧半不交叉，故视交叉之后一切按半视野而非按眼组织。模型含双侧眼球、视交叉、视束、外侧膝状体及距状沟周围枕叶皮质。",
    },
    visibleSystems: ["nervous", "skeletal"],
    modelFile: "/models/visual_pathway.glb",
    hotspots: [
      { key: "retina", meshName: "Retina.r", offset: [0, 0], label: { vi: "Võng mạc", en: "Retina", zh: "视网膜" }, latinName: "Retina",
        note: { vi: "Chặng đầu tiên và cũng là chỗ DUY NHẤT của hệ thần kinh trung ương nhìn thấy được từ ngoài qua đèn soi đáy mắt — võng mạc và đĩa thị thực chất là mô não lộ ra. Vì thế phù gai thị chính là dấu hiệu trực tiếp của tăng áp lực nội sọ, quan sát được mà không cần chọc dò.", en: "The first relay and the ONLY part of the central nervous system visible from outside through an ophthalmoscope — the retina and optic disc are brain tissue on display. Papilloedema is therefore a direct sign of raised intracranial pressure, observable without a lumbar puncture.", zh: "第一级中继，也是中枢神经系统唯一可经检眼镜自体外观察之处——视网膜与视盘实为外露的脑组织。故视乳头水肿是颅内压增高的直接征象，无需腰穿即可观察。" } },
      { key: "optic-nerve-r", meshName: "Optic nerve (II).r.001", offset: [0, 0], label: { vi: "Thần kinh thị giác (II)", en: "Optic nerve (II)", zh: "视神经（II）" }, latinName: "Nervus opticus",
        note: { vi: "Không phải dây thần kinh ngoại biên thật sự mà là một BÓ SỢI CỦA NÃO, bọc trong ba lớp màng não và có khoang dưới nhện chạy theo. Hai hệ quả lâm sàng: dịch não tuỷ tăng áp truyền thẳng ra đĩa thị gây phù gai, và dây này không tái sinh được như dây ngoại biên nên viêm thị thần kinh có thể để lại giảm thị lực vĩnh viễn. Cắt đứt một bên gây MÙ HOÀN TOÀN mắt cùng bên.", en: "Not a true peripheral nerve but a BRAIN TRACT, sheathed in all three meninges with a subarachnoid space alongside. Two consequences: raised cerebrospinal fluid pressure transmits straight to the disc as papilloedema, and it cannot regenerate like a peripheral nerve, so optic neuritis may leave permanent visual loss. Section causes TOTAL blindness of that eye.", zh: "并非真正的周围神经，而是脑的纤维束，被三层脑膜包绕并伴有蛛网膜下腔。由此有二：脑脊液压力升高直接传至视盘形成视乳头水肿；且其不能如周围神经般再生，故视神经炎可遗留永久性视力下降。切断致同侧眼全盲。" } },
      { key: "optic-chiasm", meshName: "Optic chiasm.r", offset: [0, 0], label: { vi: "Giao thoa thị giác", en: "Optic chiasm", zh: "视交叉" }, latinName: "Chiasma opticum",
        note: { vi: "Nơi sợi từ nửa võng mạc MŨI hai bên bắt chéo. Giao thoa nằm ngay TRÊN hố yên, nên u tuyến yên lớn dần đội lên ép đúng phần bắt chéo ở giữa: mất thị trường thái dương hai bên — bán manh hai thái dương, bệnh nhân kể như đeo hai miếng che ngựa và hay va vào cạnh cửa.", en: "Where the fibres from the NASAL half of each retina cross. It sits directly ABOVE the pituitary fossa, so an enlarging pituitary tumour presses on the crossing fibres in the middle: loss of both temporal fields — bitemporal hemianopia, described as wearing blinkers, with patients bumping into door frames.", zh: "两眼视网膜鼻侧半纤维交叉之处。视交叉恰位于垂体窝上方，故垂体瘤增大时压迫中央交叉纤维：双颞侧视野缺失——双颞侧偏盲，患者自述如戴马眼罩，常撞到门框。" } },
      { key: "optic-tract", meshName: "Optic tract.r", offset: [0, 0], label: { vi: "Dải thị giác", en: "Optic tract", zh: "视束" }, latinName: "Tractus opticus",
        note: { vi: "Sau giao thoa, mỗi dải thị mang thông tin của NỬA THỊ TRƯỜNG ĐỐI BÊN chứ không phải của một mắt: dải phải chở nửa thị trường trái của cả hai mắt. Vì vậy tổn thương từ đây trở đi luôn cho bán manh ĐỒNG DANH — mất cùng một nửa thị trường ở hai mắt.", en: "Past the chiasm, each tract carries the CONTRALATERAL HALF-FIELD rather than one eye: the right tract carries the left half-field of both eyes. Any lesion from here on therefore gives a HOMONYMOUS hemianopia — the same half-field lost in both eyes.", zh: "视交叉之后，每条视束携带对侧半视野而非单眼信息：右侧视束传导双眼的左半视野。故自此以后的损伤均产生同向性偏盲——双眼缺失同一半视野。" } },
      { key: "lgb", meshName: "Lateral geniculate body.r", offset: [0, 0], label: { vi: "Thể gối ngoài", en: "Lateral geniculate body", zh: "外侧膝状体" }, latinName: "Corpus geniculatum laterale",
        note: { vi: "Trạm dừng bắt buộc của đường thị giác trong đồi thị, gồm SÁU LỚP tế bào: hai lớp tế bào lớn nhận tín hiệu chuyển động và tương phản thô, bốn lớp tế bào nhỏ nhận chi tiết và màu. Mắt phải và mắt trái đổ vào các lớp XEN KẼ nhau và chưa hoà trộn — thị giác hai mắt thật sự chỉ được ghép ở vỏ não.", en: "The obligatory thalamic relay, built of SIX layers: two magnocellular layers for motion and coarse contrast, four parvocellular layers for detail and colour. The two eyes project to ALTERNATING layers and are not yet mixed — true binocular fusion happens only in the cortex.", zh: "视觉通路在丘脑的必经中继，由六层构成：两层大细胞层传导运动与粗对比，四层小细胞层传导细节与色彩。左右眼投射至交替的层且尚未融合——真正的双眼融合仅在皮质完成。" } },
      { key: "calcarine", meshName: "Calcarine sulcus.r", offset: [0, 0], label: { vi: "Rãnh cựa (vỏ thị giác V1)", en: "Calcarine sulcus (V1)", zh: "距状沟（V1）" }, latinName: "Sulcus calcarinus",
        note: { vi: "Vỏ thị giác sơ cấp nằm hai bờ rãnh này. Bản đồ thị trường ở đây bị BÓP MÉO có chủ đích: vùng hoàng điểm tuy nhỏ nhưng chiếm gần nửa diện tích vỏ, còn thị trường ngoại vi rộng lại chỉ được vài phần trăm — đúng tỉ lệ giữa chỗ ta nhìn rõ và chỗ ta chỉ cảm nhận có chuyển động.", en: "The primary visual cortex lies on both banks of this sulcus. Its field map is deliberately DISTORTED: the tiny macular area occupies nearly half the cortical surface while the vast peripheral field gets a few percent — exactly the ratio between what we see sharply and what we merely notice moving.", zh: "初级视皮质位于此沟两岸。其视野图存在刻意的放大失真：黄斑区虽小却占据近半皮质面积，而广阔的周边视野仅占百分之几——恰是我们看清之处与仅觉察运动之处的比例。" } },
      { key: "occipital-pole", meshName: "Occipital pole.r", offset: [0, 0], label: { vi: "Cực chẩm", en: "Occipital pole", zh: "枕极" }, latinName: "Polus occipitalis",
        note: { vi: "Nơi vùng HOÀNG ĐIỂM chiếu tới, và là phần được cấp máu kép bởi cả động mạch não sau lẫn nhánh tận của động mạch não giữa. Nhờ vậy nhồi máu động mạch não sau thường CHỪA LẠI thị lực trung tâm — dấu hiệu “tha hoàng điểm” giúp phân biệt tổn thương vỏ chẩm với tổn thương dải thị.", en: "The projection zone of the MACULA, with a dual supply from both the posterior cerebral artery and terminal branches of the middle cerebral artery. Posterior cerebral infarction therefore usually SPARES central vision — macular sparing distinguishes an occipital cortical lesion from an optic tract lesion.", zh: "黄斑的投射区，由大脑后动脉与大脑中动脉终末支双重供血。故大脑后动脉梗死通常保留中心视力——“黄斑回避”可鉴别枕叶皮质病变与视束病变。" } },
      { key: "cuneus", meshName: "Cuneus.r", offset: [0, 0], label: { vi: "Nêm chẩm (bờ trên rãnh cựa)", en: "Cuneus", zh: "楔叶" }, latinName: "Cuneus",
        note: { vi: "Phần vỏ NẰM TRÊN rãnh cựa, nhận tín hiệu từ nửa thị trường DƯỚI đối bên — quan hệ đảo ngược trên–dưới giữ nguyên suốt đường thị giác. Tia thị đi tới đây theo đường trên, còn sợi của thị trường trên vòng ra trước qua thuỳ thái dương (quai Meyer) nên u thái dương gây khuyết một phần tư thị trường trên.", en: "The cortex ABOVE the calcarine sulcus, receiving the contralateral LOWER field — the up-down inversion is preserved throughout the pathway. Its radiation runs directly, while upper-field fibres loop forward through the temporal lobe (Meyer's loop), so a temporal lesion gives an upper quadrantanopia.", zh: "距状沟上方的皮质，接受对侧下半视野——上下倒置关系贯穿整条通路。其视辐射径直而来，而上半视野纤维经颞叶前绕（Meyer袢），故颞叶病变致上象限盲。" } },
      { key: "superior-colliculus", meshName: "Superior colliculus.r", offset: [0, 0], label: { vi: "Củ não sinh tư trên", en: "Superior colliculus", zh: "上丘" }, latinName: "Colliculus superior",
        note: { vi: "Nhánh RẼ khỏi đường thị giác chính: một phần sợi dải thị không vào thể gối ngoài mà đi tới mái não giữa, phục vụ phản xạ quay mắt – quay đầu về phía kích thích và phản xạ đồng tử. Nhờ nhánh này mà người mù vỏ não vẫn còn phản xạ ánh sáng, còn tổn thương dây thị thì mất.", en: "A BRANCH off the main pathway: some tract fibres bypass the geniculate for the midbrain tectum, serving orienting eye and head movements and the pupillary reflex. Because of it, cortically blind patients keep their light reflex, whereas an optic nerve lesion abolishes it.", zh: "主通路的旁支：部分视束纤维不入膝状体而至中脑顶盖，服务于朝向刺激的眼头转动与瞳孔反射。故皮质盲患者仍保留光反射，而视神经损伤则消失。" } },
      { key: "oculomotor", meshName: "Oculomotor nerve (III).r.001", offset: [0, 0], label: { vi: "Thần kinh vận nhãn (III)", en: "Oculomotor nerve (III)", zh: "动眼神经（III）" }, latinName: "Nervus oculomotorius",
        note: { vi: "Không dẫn truyền hình ảnh nhưng khép kín vòng phản xạ đồng tử: sợi phó giao cảm của nó chạy NGOÀI RÌA dây, nên khối chèn ép từ ngoài (thoát vị móc hải mã, phình động mạch thông sau) làm GIÃN ĐỒNG TỬ trước khi liệt vận nhãn, còn thiếu máu do đái tháo đường thì ngược lại — liệt vận nhãn mà đồng tử còn nguyên.", en: "It carries no image but closes the pupillary reflex loop: its parasympathetic fibres run on the OUTSIDE of the nerve, so external compression (uncal herniation, posterior communicating aneurysm) DILATES the pupil before the eye movements fail, whereas diabetic ischaemia does the reverse — ophthalmoplegia with a spared pupil.", zh: "不传导图像，但闭合瞳孔反射环路：其副交感纤维走行于神经外周，故外部压迫（钩回疝、后交通动脉瘤）先致瞳孔散大而后眼球运动障碍；糖尿病缺血则相反——眼肌麻痹而瞳孔回避。" } },
      { key: "lens", meshName: "Lens.r", offset: [0, 0], label: { vi: "Thể thuỷ tinh", en: "Lens", zh: "晶状体" }, latinName: "Lens",
        note: { vi: "Thấu kính duy nhất có thể ĐỔI ĐỘ HỘI TỤ, nhờ cơ thể mi kéo giãn hay nới dây chằng treo. Sau tuổi bốn mươi, nhân thể thuỷ tinh cứng dần nên khả năng điều tiết giảm — lão thị là chuyện cơ học của mô, không phải bệnh của mắt. Khi protein trong nhân đục lại thành đục thể thuỷ tinh.", en: "The only lens that can CHANGE ITS POWER, as the ciliary muscle tightens or slackens the suspensory fibres. After forty the nucleus stiffens and accommodation fades — presbyopia is a mechanical fact of the tissue, not a disease. When its proteins opacify, the result is cataract.", zh: "唯一可改变屈光力的透镜，依靠睫状肌收缩或放松悬韧带。四十岁后晶状体核逐渐硬化，调节力下降——老视是组织的力学事实而非疾病。其蛋白混浊即为白内障。" } },
      { key: "sphenoid", meshName: "Sphenoid bone", offset: [0, 0], label: { vi: "Xương bướm (hố yên)", en: "Sphenoid bone — sella turcica", zh: "蝶骨（蝶鞍）" }, latinName: "Os sphenoidale",
        note: { vi: "Mang HỐ YÊN đỡ tuyến yên ngay dưới giao thoa và mang ống thị giác cho thần kinh thị đi qua. Chính vì tuyến yên nằm trong hố xương kín, u tuyến yên không nở ra ngoài được mà buộc phải đội LÊN TRÊN — đó là lý do giải phẫu khiến bán manh hai thái dương là triệu chứng kinh điển của nó.", en: "It carries the SELLA TURCICA cradling the pituitary right below the chiasm, and the optic canal for the nerve. Because the gland sits in a closed bony fossa, a pituitary tumour cannot expand outwards and must grow UPWARDS — the anatomical reason bitemporal hemianopia is its classic presentation.", zh: "承载位于视交叉正下方的蝶鞍以容纳垂体，并含视神经管。因垂体位于封闭骨窝内，垂体瘤无法向外扩张而只能向上生长——这正是双颞侧偏盲成为其典型表现的解剖原因。" } },
    ],
  },

  "dong-mach-canh": {
    slug: "dong-mach-canh",
    title: { vi: "Động mạch cảnh và tam giác cảnh", en: "Carotid Arteries & the Carotid Triangle", zh: "颈动脉与颈动脉三角" },
    description: {
      vi: "Trục mạch nuôi đầu – mặt – não, mở tại tam giác cảnh, vùng phẫu tích quen thuộc nhất của cổ. Động mạch cảnh chung đi lên trong bao cảnh cùng tĩnh mạch cảnh trong và dây X, tới ngang bờ trên sụn giáp thì chia đôi: động mạch cảnh TRONG không cho nhánh nào ở cổ mà chui thẳng vào sọ, còn động mạch cảnh NGOÀI cho tám nhánh nuôi toàn bộ phần ngoài sọ. Đúng chỗ chia đôi có xoang cảnh và tiểu thể cảnh — bộ cảm áp và cảm hoá học điều hoà huyết áp và hô hấp. Mảng xơ vữa cũng hay đóng đúng chỗ này, bong ra là gây đột quỵ, nên chạc ba cảnh là điểm hẹn của cả sinh lý lẫn bệnh lý mạch máu não.",
      en: "The arterial trunk of the head, opened at the carotid triangle — the most familiar dissection field of the neck. The common carotid ascends in the carotid sheath with the internal jugular vein and the vagus, dividing at the upper border of the thyroid cartilage: the INTERNAL carotid gives no branch in the neck and passes straight into the skull, while the EXTERNAL carotid gives eight branches to everything outside it. At the bifurcation lie the carotid sinus and body — baroreceptor and chemoreceptor governing blood pressure and breathing. Atheroma also settles precisely here, and embolises to cause stroke, so the bifurcation is where cerebrovascular physiology and pathology meet.",
      zh: "头面部的动脉主干，于颈动脉三角展开——颈部最经典的解剖区域。颈总动脉在颈动脉鞘内与颈内静脉、迷走神经同行，至甲状软骨上缘分叉：颈内动脉在颈部不发分支而径直入颅，颈外动脉则发出八支营养颅外全部结构。分叉处有颈动脉窦与颈动脉小球——调节血压与呼吸的压力与化学感受器。粥样斑块亦好发于此，脱落即致卒中，故分叉处正是脑血管生理与病理的交汇点。",
    },
    visibleSystems: ["cardiovascular", "muscular", "nervous", "skeletal"],
    modelFile: "/models/carotid_neck.glb",
    hotspots: [
      { key: "common-carotid", meshName: "Right common carotid artery.001", offset: [0, 0], label: { vi: "Động mạch cảnh chung", en: "Common carotid artery", zh: "颈总动脉" }, latinName: "Arteria carotis communis",
        note: { vi: "Bên phải tách từ thân tay đầu, bên trái tách thẳng từ quai động mạch chủ — nên bên trái dài hơn và có một đoạn nằm trong lồng ngực. Cả hai đi lên trong BAO CẢNH mà không cho nhánh nào, tới ngang bờ trên sụn giáp (ngang đốt sống C4) thì chia đôi.", en: "On the right it springs from the brachiocephalic trunk, on the left directly from the aortic arch — so the left is longer and has a thoracic segment. Both ascend in the CAROTID SHEATH without branching, dividing at the upper border of the thyroid cartilage (vertebral level C4).", zh: "右侧起自头臂干，左侧直接起自主动脉弓——故左侧更长且有胸段。二者均在颈动脉鞘内上行且不发分支，至甲状软骨上缘（约平C4椎体）分叉。" } },
      { key: "internal-carotid", meshName: "Internal carotid artery.r.001", offset: [0, 0], label: { vi: "Động mạch cảnh trong", en: "Internal carotid artery", zh: "颈内动脉" }, latinName: "Arteria carotis interna",
        note: { vi: "Đặc điểm nhận dạng chắc chắn nhất trong phẫu thuật: nó KHÔNG CHO NHÁNH NÀO ở cổ. Đoạn đầu phình ra thành xoang cảnh, sau đó chui vào ống động mạch cảnh của xương thái dương, uốn hình chữ S trong xoang hang rồi cấp máu cho ba phần tư trước của não. Mảng xơ vữa ở gốc mạch này là nguồn của phần lớn nhồi máu não do huyết khối động mạch tới động mạch.", en: "The surest operative identifier: it gives NO branch in the neck. Its origin bulges as the carotid sinus, then it enters the carotid canal of the temporal bone, makes an S-bend in the cavernous sinus and supplies the anterior three-quarters of the brain. Atheroma at its origin is the source of most artery-to-artery embolic strokes.", zh: "术中最可靠的辨认特征：颈部不发任何分支。起始处膨大为颈动脉窦，继而进入颞骨颈动脉管，于海绵窦内呈S形弯曲，供应大脑前3/4。其起始部的粥样斑块是大多数动脉源性栓塞性卒中的来源。" } },
      { key: "external-carotid", meshName: "External carotid artery.r.001", offset: [0, 0], label: { vi: "Động mạch cảnh ngoài", en: "External carotid artery", zh: "颈外动脉" }, latinName: "Arteria carotis externa",
        note: { vi: "Cho tám nhánh nuôi mặt, da đầu, tuyến giáp, lưỡi và màng cứng. Vì hai bên nối nhau chằng chịt qua đường giữa, thắt một bên cầm máu vẫn không hết chảy — trong chảy máu mũi nặng hay cắt u vùng hàm mặt phải tính tới vòng nối này chứ không chỉ thắt mạch cùng bên.", en: "It gives eight branches to face, scalp, thyroid, tongue and dura. Because the two sides anastomose freely across the midline, ligating one side does not stop bleeding — severe epistaxis and maxillofacial tumour surgery must reckon with that crossover, not merely tie the ipsilateral vessel.", zh: "发出八支营养面部、头皮、甲状腺、舌与硬脑膜。因两侧经中线广泛吻合，单侧结扎并不能止血——严重鼻出血与颌面肿瘤手术必须考虑此交叉吻合，而非仅结扎同侧血管。" } },
      { key: "facial-artery", meshName: "Facial artery.r.001", offset: [0, 0], label: { vi: "Động mạch mặt", en: "Facial artery", zh: "面动脉" }, latinName: "Arteria facialis",
        note: { vi: "Vòng qua bờ dưới xương hàm dưới ở trước cơ cắn — chỗ BẮT ĐƯỢC MẠCH và cũng là chỗ ép cầm máu vết thương môi má. Nó chạy ngoằn ngoèo chứ không thẳng, dự trữ sẵn chiều dài cho hàm cử động và cho môi phồng khi cười hay ăn.", en: "It hooks over the lower border of the mandible in front of masseter — where the PULSE is felt and where lip and cheek bleeding is compressed. Its course is tortuous rather than straight, storing slack for jaw movement and for the lips to stretch in speech and eating.", zh: "于咬肌前方绕过下颌骨下缘——此处可触及搏动，亦为唇颊出血的压迫止血点。其走行迂曲而非笔直，为下颌活动与唇部在言语进食时的伸展预留长度。" } },
      { key: "superficial-temporal", meshName: "Superficial temporal artery.r.001", offset: [0, 0], label: { vi: "Động mạch thái dương nông", en: "Superficial temporal artery", zh: "颞浅动脉" }, latinName: "Arteria temporalis superficialis",
        note: { vi: "Nhánh tận của động mạch cảnh ngoài, đi ngay trước bình tai và nằm rất nông. Đây là mạch được SINH THIẾT trong nghi ngờ viêm động mạch tế bào khổng lồ — bệnh gây đau đầu vùng thái dương và có nguy cơ mù đột ngột nếu không dùng corticoid kịp.", en: "A terminal branch of the external carotid, running just in front of the tragus and very superficially. This is the vessel BIOPSIED when giant cell arteritis is suspected — a disease of temporal headache that can cause sudden blindness unless steroids are started promptly.", zh: "颈外动脉终支之一，行于耳屏正前方且位置极浅。此即疑诊巨细胞动脉炎时活检的血管——该病表现为颞部头痛，若不及时使用激素可致突发失明。" } },
      { key: "internal-jugular", meshName: "Internal jugular vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch cảnh trong", en: "Internal jugular vein", zh: "颈内静脉" }, latinName: "Vena jugularis interna",
        note: { vi: "Nằm NGOÀI động mạch cảnh trong bao cảnh, là đường về của gần hết máu não. Vì thành mềm và áp lực gần bằng áp lực nhĩ phải, dao động mạch đập của nó phản ánh trực tiếp áp lực tĩnh mạch trung tâm — khám tĩnh mạch cổ nổi chính là đọc áp lực buồng tim phải bằng mắt.", en: "It lies LATERAL to the artery within the carotid sheath and drains almost all cerebral blood. Because its wall is soft and its pressure close to right atrial pressure, its pulsation directly reflects central venous pressure — inspecting the jugular veins is reading right heart pressure by eye.", zh: "位于颈动脉鞘内动脉外侧，引流几乎全部脑血。因管壁柔软且压力接近右房压，其搏动直接反映中心静脉压——观察颈静脉充盈即以肉眼读取右心压力。" } },
      { key: "vagus", meshName: "Vagus nerve (X).r.001", offset: [0, 0], label: { vi: "Thần kinh X trong bao cảnh", en: "Vagus nerve in the carotid sheath", zh: "颈动脉鞘内的迷走神经" }, latinName: "Nervus vagus",
        note: { vi: "Thành phần thứ ba của bao cảnh, nằm ở GÓC SAU giữa động mạch và tĩnh mạch. Vị trí cố định ấy khiến nó vừa là mốc phẫu thuật đáng tin vừa là cấu trúc dễ tổn thương khi bóc tách bao cảnh: chạm dây gây ho, chậm nhịp tim, cắt phải gây khàn tiếng do mất thần kinh thanh quản quặt ngược.", en: "The third occupant of the sheath, in the POSTERIOR angle between artery and vein. That constant position makes it both a reliable landmark and the structure most at risk when the sheath is opened: handling it provokes coughing and bradycardia, dividing it causes hoarseness through the recurrent laryngeal nerve.", zh: "颈动脉鞘的第三个内容物，位于动静脉之间的后角。此恒定位置使其既是可靠标志，又是打开鞘膜时最易受损的结构：牵拉引起咳嗽与心动过缓，切断则因喉返神经受累而致声嘶。" } },
      { key: "hypoglossal", meshName: "Hypoglossal nerve (XII).r.001", offset: [0, 0], label: { vi: "Thần kinh hạ thiệt (XII)", en: "Hypoglossal nerve (XII)", zh: "舌下神经（XII）" }, latinName: "Nervus hypoglossus",
        note: { vi: "Vắt ngang MẶT NGOÀI hai động mạch cảnh, ngay trên chạc ba — mốc trên của phẫu trường bóc nội mạc động mạch cảnh. Tổn thương làm lưỡi thè LỆCH VỀ BÊN BỆNH, vì cơ cằm lưỡi bên lành đẩy lưỡi sang phía không còn cơ đối trọng.", en: "It crosses SUPERFICIAL to both carotids just above the bifurcation — the upper limit of the field in carotid endarterectomy. Injury makes the protruded tongue DEVIATE TOWARDS the damaged side, because the intact genioglossus pushes it towards the side with no opposing muscle.", zh: "于分叉稍上方跨过两条颈动脉浅面——为颈动脉内膜剥脱术术野的上界。损伤后伸舌偏向患侧，因健侧颏舌肌将舌推向失去对抗肌的一侧。" } },
      { key: "sternocleidomastoid", meshName: "Sternocleidomastoid muscle.r", offset: [0, 0], label: { vi: "Cơ ức đòn chũm", en: "Sternocleidomastoid", zh: "胸锁乳突肌" }, latinName: "Musculus sternocleidomastoideus",
        note: { vi: "Chia cổ thành tam giác TRƯỚC và tam giác SAU, và là bờ sau của tam giác cảnh. Mọi đường mổ vào bao cảnh đều đi dọc bờ trước cơ này rồi vén cơ ra ngoài — đường vào giữa các lớp cân nên gần như không cắt qua cơ nào.", en: "It divides the neck into ANTERIOR and POSTERIOR triangles and forms the posterior border of the carotid triangle. Every approach to the carotid sheath runs along its anterior border and retracts it laterally — a plane between fascial layers, cutting virtually no muscle.", zh: "将颈部分为颈前三角与颈后三角，并构成颈动脉三角的后界。所有进入颈动脉鞘的切口均沿其前缘并将其向外牵开——此为筋膜层间入路，几乎不切断任何肌肉。" } },
      { key: "omohyoid", meshName: "Omohyoid muscle.r", offset: [0, 0], label: { vi: "Cơ vai móng", en: "Omohyoid", zh: "肩胛舌骨肌" }, latinName: "Musculus omohyoideus",
        note: { vi: "Cơ hai bụng nối xương bả vai với xương móng, bụng trên của nó là bờ dưới tam giác cảnh. Nhờ cắt chéo qua vùng cổ bên, nó được dùng làm MỐC CHIA TẦNG hạch cổ trong phẫu thuật ung thư đầu cổ.", en: "A two-bellied muscle running from scapula to hyoid, its superior belly forming the lower border of the carotid triangle. Crossing the lateral neck obliquely, it serves as the LANDMARK dividing the cervical node levels in head and neck cancer surgery.", zh: "连接肩胛骨与舌骨的二腹肌，其上腹构成颈动脉三角的下界。因斜跨颈侧区，被用作头颈肿瘤手术中划分颈淋巴结分区的标志。" } },
      { key: "thyroid-gland", meshName: "Thyroid gland", offset: [0, 0], label: { vi: "Tuyến giáp", en: "Thyroid gland", zh: "甲状腺" }, latinName: "Glandula thyroidea",
        note: { vi: "Nằm ngay TRONG so với bao cảnh, nên bướu giáp lớn đẩy trục mạch ra ngoài và làm mất mốc giải phẫu quen thuộc. Động mạch giáp dưới bắt chéo phía sau bao cảnh — đây là mốc giúp tìm thần kinh thanh quản quặt ngược khi mổ tuyến giáp.", en: "It sits MEDIAL to the carotid sheath, so a large goitre displaces the vessels laterally and destroys the familiar landmarks. The inferior thyroid artery crosses behind the sheath — the landmark used to find the recurrent laryngeal nerve during thyroid surgery.", zh: "位于颈动脉鞘内侧，故巨大甲状腺肿将血管推向外侧并破坏熟悉的标志。甲状腺下动脉自鞘后方跨过——此为甲状腺手术中寻找喉返神经的标志。" } },
      { key: "thyroid-cartilage", meshName: "Thyroid cartilage", offset: [0, 0], label: { vi: "Sụn giáp", en: "Thyroid cartilage", zh: "甲状软骨" }, latinName: "Cartilago thyroidea",
        note: { vi: "Bờ TRÊN của sụn này là mốc sờ được ngoài da của chạc ba động mạch cảnh (ngang C4). Chỉ cần đặt ngón tay vào bờ trên sụn giáp rồi trượt ra ngoài là chạm đúng chỗ chia đôi — thao tác dùng để bắt mạch cảnh và để xoa xoang cảnh khi cắt cơn nhịp nhanh trên thất.", en: "Its UPPER border is the palpable surface marker of the carotid bifurcation (level C4). Placing a finger on that border and sliding laterally lands exactly on the division — the manoeuvre used to feel the carotid pulse and to perform sinus massage in supraventricular tachycardia.", zh: "其上缘为颈动脉分叉的体表可触标志（平C4）。将手指置于该缘并向外滑动即触及分叉处——此手法用于触摸颈动脉搏动及室上速时的颈动脉窦按摩。" } },
    ],
  },

  "hach-co": {
    slug: "hach-co",
    title: { vi: "Hạch bạch huyết vùng cổ", en: "Cervical Lymph Nodes", zh: "颈部淋巴结" },
    description: {
      vi: "Bản đồ hạch cổ dựng theo đúng những nhóm mà lâm sàng sờ và ngoại khoa nạo vét: hạch dưới cằm, dưới hàm, mang tai, chuỗi cảnh trong sâu, hạch cổ nông dọc tĩnh mạch cảnh ngoài, hạch gai và hạch thượng đòn. Vùng cổ có tới ba trăm hạch trên tổng số khoảng tám trăm hạch của cả cơ thể, nên hạch cổ to là than phiền thường gặp bậc nhất — và cũng là chỗ mà VỊ TRÍ hạch nói lên nguồn bệnh: hạch dưới hàm dẫn lưu miệng và mặt, hạch chuỗi cảnh dẫn lưu hầu họng và thanh quản, riêng hạch thượng đòn trái nhận bạch huyết từ ổ bụng qua ống ngực nên hạch Virchow to lên là dấu hiệu ung thư dạ dày. Mốc cơ ức đòn chũm và cơ vai móng chia các nhóm thành sáu tầng dùng trong phẫu thuật.",
      en: "A map of the cervical nodes built around the groups that clinicians palpate and surgeons clear: submental, submandibular, parotid, the deep internal jugular chain, superficial nodes along the external jugular, accessory-chain and supraclavicular nodes. The neck holds some three hundred of the body's eight hundred nodes, so cervical lymphadenopathy is among the commonest complaints — and one where LOCATION names the source: submandibular nodes drain mouth and face, jugular nodes drain pharynx and larynx, while the left supraclavicular node receives abdominal lymph through the thoracic duct, so an enlarged Virchow node points to gastric cancer. Sternocleidomastoid and omohyoid divide the groups into the six surgical levels.",
      zh: "按临床触诊与外科清扫所用的分组构建颈淋巴结图谱：颏下、下颌下、腮腺、颈内静脉深链、沿颈外静脉的浅组、副链及锁骨上淋巴结。全身约八百个淋巴结中颈部占约三百个，故颈部淋巴结肿大为最常见主诉之一——且其位置即提示来源：下颌下组引流口腔与面部，颈静脉链引流咽与喉，而左锁骨上淋巴结经胸导管接受腹腔淋巴，故Virchow结肿大提示胃癌。胸锁乳突肌与肩胛舌骨肌将各组划分为外科六个分区。",
    },
    visibleSystems: ["lymphoid", "cardiovascular", "muscular", "skeletal"],
    modelFile: "/models/cervical_nodes.glb",
    hotspots: [
      { key: "submental", meshName: "Submental nodes.r", offset: [0, 0], label: { vi: "Hạch dưới cằm (tầng IA)", en: "Submental nodes (level IA)", zh: "颏下淋巴结（IA区）" }, latinName: "Nodi submentales",
        note: { vi: "Nằm giữa hai bụng trước cơ nhị thân, dẫn lưu MÔI DƯỚI giữa, cằm, sàn miệng trước và ĐẦU LƯỠI. Vì vùng dẫn lưu vắt qua đường giữa, ung thư đầu lưỡi có thể di căn hạch hai bên — lý do phẫu thuật phải nạo cả hai bên chứ không chỉ bên có u.", en: "Between the anterior bellies of digastric, draining the central LOWER LIP, chin, anterior floor of mouth and TIP OF TONGUE. Because that territory crosses the midline, a tongue-tip cancer can metastasise bilaterally — the reason surgery clears both sides, not just the side of the tumour.", zh: "位于两侧二腹肌前腹之间，引流下唇中部、颏部、口底前部与舌尖。因其引流区跨越中线，舌尖癌可双侧转移——故手术需双侧清扫而非仅患侧。" } },
      { key: "submandibular", meshName: "Submandibular nodes.r", offset: [0, 0], label: { vi: "Hạch dưới hàm (tầng IB)", en: "Submandibular nodes (level IB)", zh: "下颌下淋巴结（IB区）" }, latinName: "Nodi submandibulares",
        note: { vi: "Nằm quanh tuyến dưới hàm, dẫn lưu má, mũi ngoài, môi trên, lợi và phần trước lưỡi. Đây là nhóm hạch SƯNG ĐAU quen thuộc nhất trong viêm răng và viêm amidan ở trẻ; hạch to mà cứng, dính, không đau ở người lớn hút thuốc thì phải nghĩ tới ung thư khoang miệng.", en: "Around the submandibular gland, draining cheek, external nose, upper lip, gums and anterior tongue. This is the familiar TENDER swelling of dental sepsis and tonsillitis in children; a hard, fixed, painless node in an adult smoker must raise the question of oral cancer.", zh: "位于下颌下腺周围，引流颊部、外鼻、上唇、牙龈与舌前部。此为儿童牙源性感染与扁桃体炎时最常见的触痛性肿大；而成年吸烟者出现质硬、固定、无痛的肿大结，则须考虑口腔癌。" } },
      { key: "parotid", meshName: "Superficial parotid nodes.r", offset: [0, 0], label: { vi: "Hạch mang tai nông", en: "Superficial parotid nodes", zh: "腮腺浅淋巴结" }, latinName: "Nodi parotidei superficiales",
        note: { vi: "Nằm trên và trong tuyến mang tai — đặc điểm hiếm: tuyến mang tai là tuyến nước bọt DUY NHẤT có hạch bạch huyết nằm ngay trong nhu mô, vì tuyến hình thành sau khi hệ bạch huyết đã có. Chúng dẫn lưu da đầu vùng thái dương, vành tai và mi mắt, nên ung thư da đầu di căn tới đây trước tiên.", en: "On and within the parotid — a rarity: the parotid is the ONLY salivary gland with lymph nodes inside its parenchyma, because it encapsulates after the lymphatics have formed. They drain the temporal scalp, auricle and eyelids, so scalp skin cancers metastasise here first.", zh: "位于腮腺浅面及腺实质内——此为罕见特征：腮腺是唯一在实质内含淋巴结的涎腺，因其被膜形成晚于淋巴系统。引流颞部头皮、耳廓与眼睑，故头皮皮肤癌首先转移至此。" } },
      { key: "jugular-superior", meshName: "Lateral superior jugular node.r", offset: [0, 0], label: { vi: "Hạch cảnh trên (tầng II)", en: "Superior jugular node (level II)", zh: "颈静脉上组（II区）" }, latinName: "Nodus jugularis superior lateralis",
        note: { vi: "Nhóm hạch ĐẦU CHUỖI cảnh trong, ngay dưới bụng sau cơ nhị thân. Đây là nhóm hạch hay to nhất trong ung thư hầu mũi và ung thư amidan; ở trẻ em thì là ổ viêm hạch phản ứng thường gặp. Vì nằm sát dây XI, nạo hạch tầng này là bước dễ gây liệt cơ thang nhất.", en: "The HEAD of the internal jugular chain, just below the posterior belly of digastric. It is the node most often enlarged in nasopharyngeal and tonsillar cancer, and the commonest reactive node in children. Lying against the accessory nerve, clearing this level is the step most likely to denervate trapezius.", zh: "颈内静脉链的首端，位于二腹肌后腹下方。为鼻咽癌与扁桃体癌最常肿大的淋巴结，也是儿童最常见的反应性淋巴结。因紧邻副神经，清扫此区最易导致斜方肌失神经支配。" } },
      { key: "jugular-inferior", meshName: "Anterior inferior jugular nodes.r", offset: [0, 0], label: { vi: "Hạch cảnh dưới (tầng IV)", en: "Inferior jugular nodes (level IV)", zh: "颈静脉下组（IV区）" }, latinName: "Nodi jugulares inferiores",
        note: { vi: "Đoạn cuối chuỗi cảnh trong, dưới cơ vai móng và trên xương đòn. Chúng dẫn lưu thanh quản, tuyến giáp và thực quản cổ, đồng thời nhận bạch huyết đi lên từ NGỰC — nên hạch tầng IV to không rõ nguyên nhân buộc phải soi tìm ổ nguyên phát dưới xương đòn.", en: "The lower end of the jugular chain, below omohyoid and above the clavicle. They drain larynx, thyroid and cervical oesophagus and also receive lymph ascending from the CHEST — so an unexplained level IV node compels a search for a primary below the clavicle.", zh: "颈静脉链下段，位于肩胛舌骨肌下方、锁骨上方。引流喉、甲状腺与颈段食管，并接受来自胸部的上行淋巴——故不明原因的IV区肿大须寻找锁骨以下的原发灶。" } },
      { key: "supraclavicular", meshName: "Supraclavicular nodes.r", offset: [0, 0], label: { vi: "Hạch thượng đòn", en: "Supraclavicular nodes", zh: "锁骨上淋巴结" }, latinName: "Nodi supraclaviculares",
        note: { vi: "Nằm trong tam giác thượng đòn, nơi ống ngực (bên trái) và ống bạch huyết phải đổ vào góc tĩnh mạch. Hạch thượng đòn TRÁI to cứng — hạch Virchow — là dấu hiệu kinh điển của ung thư dạ dày, tuỵ hay buồng trứng đã lan xa, và thường sờ thấy trước khi bệnh nhân có triệu chứng tiêu hoá rõ.", en: "In the supraclavicular fossa, where the thoracic duct (left) and right lymphatic duct empty into the venous angle. A hard LEFT supraclavicular node — Virchow's node — is the classic sign of disseminated gastric, pancreatic or ovarian cancer, and is often palpable before digestive symptoms declare themselves.", zh: "位于锁骨上窝，胸导管（左）与右淋巴导管在此注入静脉角。左侧锁骨上质硬肿大结——Virchow结——是胃癌、胰腺癌或卵巢癌远处播散的经典体征，常在消化道症状明确之前即可触及。" } },
      { key: "retropharyngeal", meshName: "Retropharyngeal nodes.r", offset: [0, 0], label: { vi: "Hạch sau hầu", en: "Retropharyngeal nodes", zh: "咽后淋巴结" }, latinName: "Nodi retropharyngeales",
        note: { vi: "Nằm trong khoang sau hầu, KHÔNG SỜ ĐƯỢC từ ngoài, chỉ thấy trên phim. Chúng dẫn lưu hầu mũi, vòi tai và xoang, nên là chặng di căn đầu tiên của ung thư vòm; ở trẻ nhỏ, viêm mủ nhóm hạch này gây áp-xe sau hầu, biểu hiện bằng ưỡn cổ, chảy dãi và khó thở.", en: "In the retropharyngeal space, IMPALPABLE from outside and seen only on imaging. They drain nasopharynx, auditory tube and sinuses, making them the first station for nasopharyngeal carcinoma; in small children their suppuration produces a retropharyngeal abscess with neck extension, drooling and stridor.", zh: "位于咽后间隙，体表无法触及，仅影像可见。引流鼻咽、咽鼓管与鼻窦，故为鼻咽癌的第一站；幼儿此组化脓形成咽后脓肿，表现为颈项后仰、流涎与喘鸣。" } },
      { key: "superficial-cervical", meshName: "Superficial lateral cervical nodes.r", offset: [0, 0], label: { vi: "Hạch cổ nông", en: "Superficial cervical nodes", zh: "颈浅淋巴结" }, latinName: "Nodi cervicales laterales superficiales",
        note: { vi: "Bám dọc tĩnh mạch cảnh ngoài, ngay trên mặt cơ ức đòn chũm và DƯỚI cơ bám da cổ. Vì nông nên chúng là nhóm dễ sờ nhất; dẫn lưu vùng tuyến mang tai và da cổ, rồi đổ tiếp vào chuỗi cảnh trong sâu.", en: "Along the external jugular vein on the surface of sternocleidomastoid, deep only to platysma. Being superficial they are the easiest to palpate; they drain the parotid region and neck skin, then pass on to the deep jugular chain.", zh: "沿颈外静脉走行于胸锁乳突肌表面，仅深至颈阔肌。因位置表浅而最易触及；引流腮腺区与颈部皮肤，继而汇入颈深链。" } },
      { key: "pretracheal", meshName: "Pretracheal nodes.r", offset: [0, 0], label: { vi: "Hạch trước khí quản (tầng VI)", en: "Pretracheal nodes (level VI)", zh: "气管前淋巴结（VI区）" }, latinName: "Nodi pretracheales",
        note: { vi: "Nhóm hạch của KHOANG TRUNG TÂM cổ, nằm trước và cạnh khí quản dưới eo tuyến giáp. Đây là chặng đầu tiên của ung thư tuyến giáp thể nhú, nên nạo khoang trung tâm là bước thường quy — nhưng cũng là bước dễ làm tổn thương tuyến cận giáp và thần kinh thanh quản quặt ngược nhất.", en: "The CENTRAL COMPARTMENT group, in front of and beside the trachea below the thyroid isthmus. It is the first station for papillary thyroid carcinoma, so central compartment clearance is routine — and also the step most likely to injure the parathyroids and the recurrent laryngeal nerve.", zh: "颈部中央区淋巴结，位于甲状腺峡下方的气管前方与两侧。为甲状腺乳头状癌的第一站，故中央区清扫为常规——但也是最易损伤甲状旁腺与喉返神经的步骤。" } },
      { key: "sternocleidomastoid", meshName: "Sternocleidomastoid muscle.r", offset: [0, 0], label: { vi: "Cơ ức đòn chũm (mốc chia tầng)", en: "Sternocleidomastoid — the level landmark", zh: "胸锁乳突肌（分区标志）" }, latinName: "Musculus sternocleidomastoideus",
        note: { vi: "Cơ này phủ lên toàn bộ chuỗi cảnh trong sâu, nên hạch tầng II–IV chỉ sờ được khi bệnh nhân NGHIÊNG ĐẦU VỀ BÊN KHÁM cho cơ chùng lại. Khám hạch cổ mà để bệnh nhân ngồi thẳng căng cơ là bỏ sót chính nhóm hạch quan trọng nhất.", en: "It covers the entire deep jugular chain, so level II–IV nodes are palpable only when the patient TILTS THE HEAD TOWARDS the examined side to slacken the muscle. Examining the neck with the head upright and the muscle taut misses exactly the group that matters most.", zh: "该肌覆盖整条颈深链，故II–IV区淋巴结仅在患者将头偏向受检侧使肌肉松弛时方可触及。若令患者端坐使该肌紧张进行检查，恰会漏掉最重要的一组。" } },
      { key: "internal-jugular", meshName: "Internal jugular vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch cảnh trong (trục của chuỗi hạch)", en: "Internal jugular vein — axis of the chain", zh: "颈内静脉（淋巴链之轴）" }, latinName: "Vena jugularis interna",
        note: { vi: "Chuỗi hạch cổ sâu bám DỌC tĩnh mạch này suốt từ nền sọ tới gốc cổ, nên nạo vét hạch cổ triệt để cổ điển phải lấy cả tĩnh mạch. Phẫu thuật ngày nay cố GIỮ LẠI tĩnh mạch khi hạch chưa xâm lấn, vì cắt cả hai bên gây phù mặt và tăng áp lực nội sọ.", en: "The deep cervical chain hugs this vein from skull base to root of neck, which is why the classical radical neck dissection removed the vein with the nodes. Modern surgery PRESERVES it when the nodes have not invaded, since bilateral removal causes facial oedema and raised intracranial pressure.", zh: "颈深淋巴链自颅底至颈根紧贴此静脉，故经典根治性颈清扫需连同静脉一并切除。现代手术在淋巴结未侵犯时予以保留，因双侧切除可致面部水肿与颅内压增高。" } },
    ],
  },

  "tuyen-giap": {
    slug: "tuyen-giap",
    title: { vi: "Tuyến giáp và tuyến cận giáp", en: "Thyroid & Parathyroid Glands", zh: "甲状腺与甲状旁腺" },
    description: {
      vi: "Tuyến nội tiết lớn nhất cơ thể cùng bốn tuyến cận giáp bé xíu nép sau nó — hai tuyến khác nhau hoàn toàn về chức năng nhưng dính nhau về giải phẫu, và chính sự dính nhau đó chi phối toàn bộ phẫu thuật vùng cổ. Tuyến giáp có hai thuỳ ôm hai bên khí quản nối bằng eo tuyến bắc ngang vòng sụn khí quản 2–4; nó được bao tạng giữ chặt vào thanh – khí quản nên DI ĐỘNG THEO NHỊP NUỐT, dấu hiệu phân biệt bướu giáp với mọi khối u khác ở cổ. Bốn tuyến cận giáp chỉ bằng hạt gạo, nằm mặt sau hai thuỳ, giữ canxi máu; cắt nhầm cả bốn gây cơn tetani hạ canxi vài giờ sau mổ. Giữa hai tuyến là thần kinh thanh quản quặt ngược đi trong rãnh khí – thực quản, dây thần kinh mà mọi phẫu thuật viên tuyến giáp đều phải tìm thấy trước khi cắt.",
      en: "The body's largest endocrine gland with the four tiny parathyroids tucked behind it — functionally unrelated, anatomically inseparable, and that inseparability governs all neck surgery. The thyroid's two lobes flank the trachea, joined by an isthmus over tracheal rings two to four; the pretracheal fascia binds it to the larynx so it MOVES ON SWALLOWING, the sign that separates a goitre from every other neck mass. The four parathyroids, each the size of a grain of rice on the posterior surface, control blood calcium; removing all four causes hypocalcaemic tetany hours after surgery. Between the two runs the recurrent laryngeal nerve in the tracheo-oesophageal groove — the nerve every thyroid surgeon must find before cutting.",
      zh: "人体最大的内分泌腺与藏于其后的四个微小甲状旁腺——功能迥异却解剖相连，而这种相连支配着全部颈部手术。甲状腺两叶夹持气管，峡部跨越第2–4气管环；气管前筋膜将其固定于喉，故随吞咽上下移动，此为甲状腺肿与其他颈部肿块的鉴别征象。四个甲状旁腺各如米粒大小，位于两叶后面，调控血钙；四腺全切致术后数小时内低钙性手足搐搦。二者之间为行于气管食管沟内的喉返神经——甲状腺外科医师在切割前必须找到的神经。",
    },
    visibleSystems: ["visceral", "cardiovascular", "muscular", "skeletal"],
    modelFile: "/models/thyroid_parathyroid.glb",
    hotspots: [
      { key: "thyroid-gland", meshName: "Thyroid gland", offset: [0, 0], label: { vi: "Tuyến giáp", en: "Thyroid gland", zh: "甲状腺" }, latinName: "Glandula thyroidea",
        note: { vi: "Tuyến nội tiết duy nhất DỰ TRỮ hormone ngoài tế bào, trong lòng nang chứa keo — đủ dùng vài tháng, nên bệnh tuyến giáp diễn biến chậm và thuốc kháng giáp cũng phải vài tuần mới có tác dụng. Tuyến nhận lưu lượng máu rất lớn so với kích thước, vì thế bướu giáp nhiễm độc có thể nghe được tiếng thổi ngay trên tuyến.", en: "The only endocrine gland that STORES its hormone outside the cell, in colloid-filled follicles — months' worth, which is why thyroid disease evolves slowly and antithyroid drugs take weeks to work. It receives an enormous blood flow for its size, so a toxic goitre may have an audible bruit over it.", zh: "唯一在细胞外储存激素的内分泌腺，储于充满胶质的滤泡中——足够数月之用，故甲状腺疾病进展缓慢，抗甲状腺药亦需数周起效。相对其体积其血流量极大，故毒性甲状腺肿表面可闻及血管杂音。" } },
      { key: "parathyroid-sup", meshName: "Superior parathyroid gland.r", offset: [0, 0], label: { vi: "Tuyến cận giáp trên", en: "Superior parathyroid gland", zh: "上甲状旁腺" }, latinName: "Glandula parathyroidea superior",
        note: { vi: "Sinh ra từ TÚI MANG THỨ TƯ nên đường di cư ngắn, vị trí khá hằng định ở mặt sau thuỳ giáp ngang chỗ nối một phần ba trên. Nó nằm SÂU hơn so với mặt phẳng của thần kinh thanh quản quặt ngược — quan hệ này là mẹo định vị chắc chắn nhất khi tìm tuyến trong mổ.", en: "Derived from the FOURTH pharyngeal pouch, its migration is short and its position fairly constant on the back of the lobe at the upper-third junction. It lies DEEP to the plane of the recurrent laryngeal nerve — a relationship that is the surest trick for locating it at operation.", zh: "源自第四咽囊，迁移路径短，位置较恒定，位于甲状腺叶后面上中1/3交界处。其位于喉返神经平面的深面——此关系是术中定位最可靠的窍门。" } },
      { key: "parathyroid-inf", meshName: "Inferior parathyroid gland.r", offset: [0, 0], label: { vi: "Tuyến cận giáp dưới", en: "Inferior parathyroid gland", zh: "下甲状旁腺" }, latinName: "Glandula parathyroidea inferior",
        note: { vi: "Sinh ra từ TÚI MANG THỨ BA cùng tuyến ức và phải di cư xuống rất xa, nên vị trí thất thường nhất: có thể nằm cạnh cực dưới thuỳ giáp, trong dây chằng giáp – ức, hay lạc chỗ hẳn vào trung thất theo tuyến ức. Đó là lý do khi mổ cường cận giáp mà không tìm thấy tuyến bệnh thì phải tìm tiếp trong ngực.", en: "Derived from the THIRD pouch together with the thymus, it migrates far and is the most variable: beside the lower pole, in the thyrothymic ligament, or carried right down into the mediastinum with the thymus. Hence, in surgery for hyperparathyroidism, a missing gland must be sought in the chest.", zh: "与胸腺同源自第三咽囊，迁移距离长，位置最不恒定：可位于甲状腺下极旁、甲状腺胸腺韧带内，或随胸腺降入纵隔。故甲状旁腺功能亢进手术中若未找到病变腺体，须继续在胸内寻找。" } },
      { key: "trachea", meshName: "Trachea", offset: [0, 0], label: { vi: "Khí quản", en: "Trachea", zh: "气管" }, latinName: "Trachea",
        note: { vi: "Bị eo tuyến giáp bắc ngang ở vòng sụn 2–4. Bướu giáp lớn ép khí quản gây khó thở khi nằm và tiếng rít; ép lâu làm nhuyễn sụn khí quản, nên sau khi cắt bướu to, khí quản có thể XẸP LẠI ngay khi rút ống nội khí quản — biến chứng phải lường trước chứ không xử trí kịp lúc xảy ra.", en: "Crossed by the thyroid isthmus at rings two to four. A large goitre compresses it, giving positional dyspnoea and stridor; long compression softens the cartilage, so after removing a big goitre the trachea may COLLAPSE the moment the tube is withdrawn — a complication to anticipate rather than react to.", zh: "甲状腺峡部于第2–4气管环处横跨其上。巨大甲状腺肿压迫之，引起体位性呼吸困难与喘鸣；长期受压致气管软化，故切除巨大甲状腺肿后拔管瞬间气管可能塌陷——此并发症须预先防范而非临时处置。" } },
      { key: "inferior-thyroid-artery", meshName: "Inferior thyroid artery.r.001", offset: [0, 0], label: { vi: "Động mạch giáp dưới", en: "Inferior thyroid artery", zh: "甲状腺下动脉" }, latinName: "Arteria thyroidea inferior",
        note: { vi: "Nhánh của thân giáp cổ, đi ngang vào cực dưới thuỳ giáp và BẮT CHÉO thần kinh thanh quản quặt ngược — có thể trước, sau, hoặc kẹp dây giữa các nhánh. Chính vì quan hệ thất thường ấy mà nguyên tắc mổ là buộc mạch SÁT BAO TUYẾN, không buộc thân chính ở xa, để khỏi kẹp phải dây thần kinh và để khỏi cắt máu nuôi tuyến cận giáp.", en: "A branch of the thyrocervical trunk entering the lower pole and CROSSING the recurrent laryngeal nerve — in front, behind, or with the nerve between its branches. Because that relationship is unpredictable, the rule is to ligate the vessels ON THE CAPSULE rather than the main trunk at a distance, sparing both the nerve and the parathyroid blood supply.", zh: "甲状颈干的分支，横行进入甲状腺下极并与喉返神经交叉——可在其前、其后，或神经穿行于其分支之间。因该关系不可预测，手术原则为紧贴腺被膜结扎血管而非远处结扎主干，以同时保护神经与甲状旁腺血供。" } },
      { key: "superior-thyroid-vein", meshName: "Superior thyroid vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch giáp trên", en: "Superior thyroid vein", zh: "甲状腺上静脉" }, latinName: "Vena thyroidea superior",
        note: { vi: "Đổ vào tĩnh mạch cảnh trong. Cùng với tĩnh mạch giáp giữa và dưới, chúng tạo một đám rối rất phát triển trên bề mặt tuyến — lý do vì sao chỉ một vết rạch nhỏ vào bướu giáp cũng chảy máu nhiều, và vì sao cầm máu tỉ mỉ quan trọng hơn thao tác nhanh trong mổ tuyến giáp.", en: "It drains into the internal jugular vein. With the middle and inferior thyroid veins it forms a rich surface plexus — the reason even a small incision into a goitre bleeds briskly, and why meticulous haemostasis matters more than speed in thyroid surgery.", zh: "注入颈内静脉。与甲状腺中、下静脉共同在腺表面形成丰富的静脉丛——这解释了为何切开甲状腺肿即使切口很小也出血汹涌，也说明甲状腺手术中细致止血比操作迅速更重要。" } },
      { key: "vagus", meshName: "Vagus nerve (X).r.001", offset: [0, 0], label: { vi: "Thần kinh X (nguồn của dây quặt ngược)", en: "Vagus nerve — source of the recurrent nerve", zh: "迷走神经（喉返神经的来源）" }, latinName: "Nervus vagus",
        note: { vi: "Dây quặt ngược tách từ dây X trong lồng ngực rồi CHẠY NGƯỢC LÊN trong rãnh khí – thực quản để vào thanh quản. Khoảng 0,5–1% người bên PHẢI có dây “không quặt ngược” đi thẳng từ cổ vào thanh quản — biến thể luôn đi kèm bất thường động mạch dưới đòn phải, và là bẫy khiến phẫu thuật viên cắt nhầm vì tìm dây ở sai chỗ.", en: "The recurrent nerve leaves the vagus in the thorax and RUNS BACK UP the tracheo-oesophageal groove into the larynx. In 0.5–1% of people the RIGHT nerve is non-recurrent, entering directly from the neck — a variant always accompanying an aberrant right subclavian artery, and the classic trap in which the surgeon divides the nerve while searching in the wrong place.", zh: "喉返神经在胸内自迷走神经发出，沿气管食管沟返行向上入喉。约0.5–1%的人右侧为“非返性”喉神经，自颈部直接入喉——此变异必伴右锁骨下动脉迷走，是外科医师因在错误位置寻找而误断神经的经典陷阱。" } },
      { key: "cricothyroid", meshName: "Straight part of cricothyroid muscle.r", offset: [0, 0], label: { vi: "Cơ nhẫn giáp", en: "Cricothyroid muscle", zh: "环甲肌" }, latinName: "Musculus cricothyroideus",
        note: { vi: "Cơ căng dây thanh, cơ DUY NHẤT của thanh quản không do dây quặt ngược chi phối mà do nhánh ngoài của thần kinh thanh quản trên — dây chạy sát động mạch giáp trên ở cực trên tuyến. Cắt phải nhánh này không gây khàn nặng mà làm MẤT GIỌNG CAO: ca sĩ và giáo viên mất nghề, nên nó được gọi là “dây thần kinh của giọng hát”.", en: "The vocal cord tensor, the ONLY laryngeal muscle not supplied by the recurrent nerve but by the external branch of the superior laryngeal nerve, which runs beside the superior thyroid artery at the upper pole. Injuring it causes not hoarseness but LOSS OF HIGH NOTES — career-ending for singers and teachers, hence its name, the nerve of the singing voice.", zh: "声带紧张肌，是唯一不由喉返神经而由喉上神经外支支配的喉肌，该神经在腺上极紧邻甲状腺上动脉走行。损伤后并非明显声嘶，而是失去高音——对歌唱者与教师可致职业终结，故被称为“歌唱神经”。" } },
      { key: "thyroid-cartilage", meshName: "Thyroid cartilage", offset: [0, 0], label: { vi: "Sụn giáp", en: "Thyroid cartilage", zh: "甲状软骨" }, latinName: "Cartilago thyroidea",
        note: { vi: "Mốc sờ được để định vị tuyến: thuỳ giáp nằm ngay dưới và hai bên sụn này. Tuyến giáp DÍNH vào sụn qua dây chằng treo, đó chính là cơ chế khiến tuyến đi lên khi nuốt — nghiệm pháp một giây phân biệt bướu giáp với hạch cổ, nang giáp lưỡi hay u mỡ.", en: "The palpable landmark: the lobes sit just below and beside it. The gland is TETHERED to the cartilage by the suspensory ligament, which is why it rises on swallowing — a one-second test separating a goitre from a lymph node, a thyroglossal cyst or a lipoma.", zh: "可触及的定位标志：甲状腺两叶恰位于其下方两侧。腺体经悬韧带固定于软骨，故吞咽时随之上移——此一秒钟的检查即可将甲状腺肿与淋巴结、甲状舌管囊肿或脂肪瘤区分开。" } },
      { key: "sternohyoid", meshName: "Sternohyoid muscle.r", offset: [0, 0], label: { vi: "Cơ ức móng (nhóm cơ dưới móng)", en: "Sternohyoid — the strap muscles", zh: "胸骨舌骨肌（带状肌群）" }, latinName: "Musculus sternohyoideus",
        note: { vi: "Lớp cơ dẹt phủ trước tuyến giáp. Đường mổ tuyến giáp TÁCH ĐÔI hai cơ này theo đường giữa — một đường vô mạch — chứ không cắt ngang; nhờ vậy sau mổ nuốt và nói gần như không bị ảnh hưởng. Chỉ bướu rất lớn mới phải cắt ngang cơ, và khi ấy phải cắt ở PHẦN CAO để chừa lại nhánh thần kinh vào cơ.", en: "The flat muscles in front of the gland. Thyroid incisions SPLIT them in the avascular midline rather than cutting across, which is why swallowing and voice are barely affected afterwards. Only a very large goitre requires transection, and then it is done HIGH to spare the nerve supply entering below.", zh: "覆于甲状腺前方的扁肌。甲状腺手术沿无血管的中线将其分开而非横断，故术后吞咽与发声几乎不受影响。仅巨大甲状腺肿需横断，且须在高位切断以保留自下方进入的神经支。" } },
      { key: "thyroid-nodes", meshName: "Thyroid nodes.r", offset: [0, 0], label: { vi: "Hạch quanh tuyến giáp", en: "Thyroid lymph nodes", zh: "甲状腺淋巴结" }, latinName: "Nodi lymphoidei thyroidei",
        note: { vi: "Bạch huyết tuyến giáp đổ về hạch trước – cạnh khí quản rồi lên chuỗi cảnh sâu. Ung thư tuyến giáp thể NHÚ di căn hạch rất sớm và rất hay, nhưng nghịch lý là tiên lượng vẫn tốt — hạch dương tính ở thể nhú không mang ý nghĩa nặng nề như ở hầu hết ung thư khác.", en: "Thyroid lymph drains to the pretracheal and paratracheal nodes, then up the deep cervical chain. PAPILLARY carcinoma metastasises to nodes early and often, yet the prognosis stays good — positive nodes here do not carry the grim weight they do in most other cancers.", zh: "甲状腺淋巴引流至气管前与气管旁淋巴结，继而沿颈深链上行。乳头状癌很早且很常发生淋巴结转移，但预后依然良好——此处淋巴结阳性并不具备多数其他癌症中的严重意义。" } },
    ],
  },

  "vung-nguc-tuyen-vu": {
    slug: "vung-nguc-tuyen-vu",
    title: { vi: "Vùng ngực trước và tuyến vú", en: "Pectoral Region & the Breast", zh: "胸前区与乳房" },
    description: {
      vi: "Thành ngực trước với hai cơ ngực, vùng vú và toàn bộ đường dẫn lưu bạch huyết ra hố nách — vùng giải phẫu chi phối cách khám và cách mổ ung thư vú. Tuyến vú nằm trong lớp mỡ dưới da, TRƯỚC mạc ngực, ngăn cách với cơ ngực lớn bởi khoang sau tuyến giúp vú trượt được trên thành ngực; ung thư ăn qua khoang này thì vú mất di động, ăn theo dây chằng treo Cooper thì da bị kéo lõm, tắc bạch mạch da thì da sần như vỏ cam. Ba phần tư bạch huyết của vú đổ về hạch NÁCH theo bậc I → II → III, phần còn lại về hạch cạnh ức, nên nạo vét hạch nách và sinh thiết hạch cửa đều dựa trên chính bản đồ này.",
      en: "The anterior chest wall with both pectoral muscles, the breast, and the whole lymphatic drainage into the axilla — the anatomy that dictates how breast cancer is examined and operated. The breast lies in the subcutaneous fat IN FRONT of the pectoral fascia, separated from pectoralis major by the retromammary space that lets it glide; cancer crossing that space fixes the breast, cancer along Cooper's ligaments tethers and dimples the skin, and blocked dermal lymphatics give peau d'orange. Three-quarters of breast lymph drains to the AXILLARY nodes through levels I → II → III and the rest to the parasternal nodes, so both axillary clearance and sentinel node biopsy rest on this map.",
      zh: "含双侧胸肌的胸前壁、乳房及其向腋窝的全部淋巴引流——决定乳腺癌查体与手术方式的解剖。乳房位于皮下脂肪层内、胸肌筋膜前方，借乳房后间隙与胸大肌分隔而可滑动；癌肿越过该间隙则乳房固定，沿Cooper韧带蔓延则皮肤牵拉凹陷，真皮淋巴管阻塞则呈橘皮样改变。乳房淋巴的3/4经I→II→III级引流至腋淋巴结，其余至胸骨旁淋巴结，故腋窝清扫与前哨淋巴结活检均以此图谱为据。",
    },
    visibleSystems: ["muscular", "lymphoid", "cardiovascular", "skeletal"],
    modelFile: "/models/pectoral_breast.glb",
    hotspots: [
      { key: "mammary-region", meshName: "Mammary region.r", offset: [0, 0], label: { vi: "Vùng vú", en: "Mammary region", zh: "乳房区" }, latinName: "Regio mammaria",
        note: { vi: "Trải từ xương sườn II tới VI và từ bờ xương ức tới đường nách giữa, kèm ĐUÔI NÁCH kéo dài lên hố nách qua lỗ mạc. Đuôi nách là lý do khám vú phải sờ cả tới nách, và là chỗ mà một khối u dễ bị bỏ sót vì người khám dừng tay ở bờ ngoài vú.", en: "It spans ribs two to six and from the sternal edge to the mid-axillary line, with an AXILLARY TAIL running up into the axilla through the fascial opening. That tail is why breast examination must reach into the axilla, and where a lump is missed when the examiner stops at the lateral breast border.", zh: "自第2至第6肋、自胸骨缘至腋中线，并有腋尾经筋膜孔伸入腋窝。腋尾的存在使乳房检查必须延伸至腋窝，也是检查者止步于乳房外缘时容易漏诊肿块之处。" } },
      { key: "inframammary", meshName: "Inframammary region.r", offset: [0, 0], label: { vi: "Nếp dưới vú", en: "Inframammary fold", zh: "乳房下皱襞" }, latinName: "Sulcus inframammarius",
        note: { vi: "Nếp da nơi mô vú dừng lại và mạc nông bám chắc vào thành ngực. Đây là ranh giới GIẢI PHẪU CỐ ĐỊNH nhất của vú, nên phẫu thuật thẩm mỹ lẫn tạo hình sau cắt vú đều lấy nếp này làm mốc dựng lại hình dáng — và cũng là nơi da hay hăm, viêm ở người có vú lớn.", en: "The skin crease where breast tissue ends and the superficial fascia anchors to the chest wall. It is the most CONSTANT anatomical boundary of the breast, so both cosmetic and reconstructive surgery use it as the reference for rebuilding shape — and it is where intertrigo develops in large breasts.", zh: "乳腺组织终止、浅筋膜锚定于胸壁处的皮肤皱襞。为乳房最恒定的解剖界限，故整形与乳房重建手术均以之为重塑形态的参照——亦为乳房丰满者易发擦烂性皮炎之处。" } },
      { key: "pectoralis-major", meshName: "Sternocostal head of pectoralis major muscle.r", offset: [0, 0], label: { vi: "Cơ ngực lớn (bó ức sườn)", en: "Pectoralis major — sternocostal head", zh: "胸大肌（胸肋头）" }, latinName: "Musculus pectoralis major",
        note: { vi: "Nền của tuyến vú. Cho bệnh nhân CHỐNG TAY VÀO HÔNG rồi ép mạnh làm cơ này căng lên: khối u dính vào cơ sẽ mất di động theo hướng sợi cơ — nghiệm pháp cũ nhưng vẫn là cách khám tại giường nhanh nhất để đánh giá xâm lấn sâu.", en: "The floor on which the breast lies. Asking the patient to PRESS HANDS ON HIPS contracts it: a tumour fixed to the muscle loses mobility along the fibre direction — an old test, still the fastest bedside way to judge deep invasion.", zh: "乳房所依附的基底。嘱患者双手叉腰用力下压使该肌收缩：与肌肉固定的肿块沿肌纤维方向失去活动度——此为古老却仍是床旁判断深部浸润最快的方法。" } },
      { key: "pectoralis-minor", meshName: "Pectoralis minor muscle.r", offset: [0, 0], label: { vi: "Cơ ngực bé", en: "Pectoralis minor", zh: "胸小肌" }, latinName: "Musculus pectoralis minor",
        note: { vi: "Bám từ sườn III–V lên mỏm quạ, bắc ngang qua hố nách và vì thế được dùng làm mốc CHIA BẬC hạch nách: bậc I ở ngoài cơ, bậc II sau cơ, bậc III trong cơ. Cách chia này quyết định phạm vi nạo vét trong phẫu thuật ung thư vú.", en: "From ribs three to five up to the coracoid process, crossing the axilla and therefore used as the landmark for the axillary node LEVELS: level I lateral to it, level II behind it, level III medial to it. That division defines the extent of clearance in breast cancer surgery.", zh: "起自第3–5肋止于喙突，横跨腋窝，故用作腋淋巴结分级的标志：I级位于其外侧，II级位于其后方，III级位于其内侧。此划分决定乳腺癌手术清扫的范围。" } },
      { key: "axillary-nodes", meshName: "Lateral axillary nodes.r", offset: [0, 0], label: { vi: "Hạch nách bậc I", en: "Level I axillary nodes", zh: "I级腋淋巴结" }, latinName: "Nodi axillares laterales",
        note: { vi: "Nhóm hạch NGOÀI cơ ngực bé, nhận phần lớn bạch huyết của vú và của chi trên. Đây là nhóm hạch sờ được khi khám và là nơi hạch CỬA (hạch đầu tiên nhận bạch huyết từ u) nằm trong hơn chín mươi phần trăm trường hợp — cơ sở của sinh thiết hạch cửa thay cho nạo vét toàn bộ.", en: "The group LATERAL to pectoralis minor, receiving most lymph from the breast and the upper limb. These are the palpable nodes on examination and where the SENTINEL node — the first to receive lymph from the tumour — lies in over ninety percent of cases, the basis for sentinel biopsy replacing full clearance.", zh: "位于胸小肌外侧的一组，接受乳房与上肢的大部分淋巴。为查体时可触及的淋巴结，且逾九成病例的前哨淋巴结（最先接受肿瘤淋巴引流者）位于此组——此即以前哨活检替代全腋清扫的依据。" } },
      { key: "apical-nodes", meshName: "Apical axillary nodes.r", offset: [0, 0], label: { vi: "Hạch đỉnh nách (bậc III)", en: "Apical axillary nodes (level III)", zh: "腋尖淋巴结（III级）" }, latinName: "Nodi axillares apicales",
        note: { vi: "Nhóm cao nhất, nằm TRONG cơ ngực bé sát đỉnh hố nách, là trạm cuối trước khi bạch huyết đổ vào thân dưới đòn. Hạch bậc III dương tính báo hiệu bệnh đã đi xa; nạo tới bậc này làm tăng rõ nguy cơ PHÙ BẠCH MẠCH cánh tay, nên chỉ làm khi thật cần.", en: "The highest group, MEDIAL to pectoralis minor at the apex of the axilla, the last station before lymph enters the subclavian trunk. Positive level III nodes signal advanced disease; clearing to this level markedly raises the risk of arm LYMPHOEDEMA, so it is done only when necessary.", zh: "最高的一组，位于胸小肌内侧、腋窝尖部，为淋巴汇入锁骨下干前的最后一站。III级阳性提示病变已属晚期；清扫至此级显著增加上肢淋巴水肿风险，故仅在必要时进行。" } },
      { key: "interpectoral", meshName: "Interpectoral nodes.r", offset: [0, 0], label: { vi: "Hạch gian cơ ngực (hạch Rotter)", en: "Interpectoral (Rotter) nodes", zh: "胸肌间（Rotter）淋巴结" }, latinName: "Nodi interpectorales",
        note: { vi: "Nằm KẸP GIỮA cơ ngực lớn và cơ ngực bé — vị trí khiến chúng bị bỏ sót trong phẫu thuật bảo tồn cơ nếu không chủ động tìm. Di căn tại đây là một trong những lý do bệnh tái phát tại thành ngực dù hạch nách đã được nạo sạch.", en: "Sandwiched BETWEEN the two pectoral muscles — a position that hides them in muscle-sparing surgery unless deliberately sought. Metastasis here is one reason for chest wall recurrence despite an apparently complete axillary clearance.", zh: "夹于胸大肌与胸小肌之间——此位置使其在保留肌肉的手术中若不刻意寻找便会遗漏。此处转移是腋窝看似清扫彻底仍出现胸壁复发的原因之一。" } },
      { key: "parasternal", meshName: "Parasternal nodes.r", offset: [0, 0], label: { vi: "Hạch cạnh ức", en: "Parasternal nodes", zh: "胸骨旁淋巴结" }, latinName: "Nodi parasternales",
        note: { vi: "Bám dọc động mạch ngực trong, nhận bạch huyết của NỬA TRONG tuyến vú. Vì chúng nằm sâu sau sụn sườn nên không sờ được và không nạo được qua đường nách — ung thư ở góc phần tư trong có thể di căn theo đường này mà hạch nách vẫn âm tính, một cạm bẫy của giai đoạn lâm sàng.", en: "Along the internal thoracic artery, draining the MEDIAL half of the breast. Lying deep to the costal cartilages they are neither palpable nor reachable through the axilla — a medial quadrant cancer can spread this way with a negative axilla, a pitfall of clinical staging.", zh: "沿胸廓内动脉排列，引流乳房内侧半。因深居肋软骨后方，既不可触及亦无法经腋窝清扫——内侧象限的癌肿可经此路径转移而腋窝阴性，是临床分期的陷阱。" } },
      { key: "internal-thoracic", meshName: "Internal thoracic artery.r.001", offset: [0, 0], label: { vi: "Động mạch ngực trong", en: "Internal thoracic artery", zh: "胸廓内动脉" }, latinName: "Arteria thoracica interna",
        note: { vi: "Chạy dọc sau sụn sườn, cách bờ xương ức khoảng một khoát ngón tay, cho các nhánh XUYÊN nuôi nửa trong tuyến vú. Nó cũng là mạch được lấy làm cầu nối trong mổ bắc cầu động mạch vành — cầu nối bằng chính động mạch này có tuổi thọ dài hơn hẳn cầu nối bằng tĩnh mạch hiển.", en: "Running behind the costal cartilages about a finger's breadth from the sternal edge, sending PERFORATING branches to the medial breast. It is also the graft of choice in coronary bypass — a conduit that outlasts a saphenous vein graft by a wide margin.", zh: "行于肋软骨后方、距胸骨缘约一横指处，发出穿支营养乳房内侧部。其亦为冠状动脉搭桥的首选桥血管——以此动脉为桥的通畅时间远超大隐静脉桥。" } },
      { key: "long-thoracic", meshName: "Long thoracic nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh ngực dài", en: "Long thoracic nerve", zh: "胸长神经" }, latinName: "Nervus thoracicus longus",
        note: { vi: "Đi thẳng trên mặt cơ răng trước ở thành trong hố nách. Cùng với thần kinh ngực lưng, đây là dây phải BẢO TỒN khi nạo hạch nách; cắt phải gây xương bả vai cánh, làm bệnh nhân không giơ tay quá đầu được — di chứng vĩnh viễn của một sai lầm vài giây.", en: "It runs directly on serratus anterior on the medial wall of the axilla. With the thoracodorsal nerve it is the nerve to PRESERVE during axillary clearance; dividing it gives a winged scapula and an inability to raise the arm overhead — a permanent legacy of a few seconds' error.", zh: "直接行于腋窝内侧壁的前锯肌表面。与胸背神经同为腋窝清扫时必须保留的神经；切断后致翼状肩胛，患者无法上举过头——数秒之失造成的永久后遗。" } },
      { key: "thoracodorsal", meshName: "Thoracodorsal nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh ngực lưng", en: "Thoracodorsal nerve", zh: "胸背神经" }, latinName: "Nervus thoracodorsalis",
        note: { vi: "Chi phối cơ lưng rộng, đi cùng bó mạch cùng tên ở thành sau hố nách. Giữ được dây này không chỉ để bảo tồn chức năng: vạt cơ lưng rộng có cuống mạch – thần kinh nguyên vẹn là một trong những cách TẠO HÌNH VÚ tin cậy nhất sau cắt tuyến.", en: "Supplying latissimus dorsi and running with its vessels on the posterior axillary wall. Preserving it is not only about function: a latissimus flap with an intact neurovascular pedicle is one of the most reliable ways to RECONSTRUCT a breast after mastectomy.", zh: "支配背阔肌，与同名血管束伴行于腋窝后壁。保留该神经不仅为保留功能：带完整血管神经蒂的背阔肌瓣是乳房切除后最可靠的重建方式之一。" } },
      { key: "serratus", meshName: "Serratus anterior muscle.r", offset: [0, 0], label: { vi: "Cơ răng trước", en: "Serratus anterior", zh: "前锯肌" }, latinName: "Musculus serratus anterior",
        note: { vi: "Lát thành TRONG của hố nách và giữ xương bả vai áp vào lồng ngực. Trong gây tê vùng, khoang giữa cơ này và cơ lưng rộng là đích của phong bế mặt phẳng cơ răng trước — cách giảm đau hiệu quả cho gãy nhiều xương sườn và cho mổ vú mà không cần gây tê ngoài màng cứng.", en: "It lines the MEDIAL wall of the axilla and holds the scapula against the chest. In regional anaesthesia the plane between it and latissimus dorsi is the target of the serratus anterior plane block — effective analgesia for multiple rib fractures and breast surgery without an epidural.", zh: "构成腋窝内侧壁并将肩胛骨固定于胸壁。区域麻醉中，其与背阔肌之间的间隙是前锯肌平面阻滞的靶点——为多发肋骨骨折与乳房手术提供有效镇痛而无需硬膜外麻醉。" } },
    ],
  },
});

